    var arr=raw?JSON.parse(raw):[];
    if(!Array.isArray(arr)) arr=[];
    arr.push(Date.now());
    if(arr.length>WD_LOG_MAX) arr=arr.slice(-WD_LOG_MAX);
    localStorage.setItem(WD_LOG_KEY, JSON.stringify(arr));
