// Computes a comparable training-stress number for any activity type.
// Cycling activities with power data already have a real TSS (Coggan formula).
// Everything else (runs, strength, mobility, etc.) falls back to:
//   1. hrTSS - based on avg HR relative to estimated lactate threshold HR
//      (LTHR estimated as 88% of max HR when not otherwise known - a standard
//      approximation, per Friel, when no formal threshold test exists)
//   2. RPE x duration (Foster's session-RPE method) when no HR data exists
// This lets one CTL/ATL/TSB model represent total load across every sport,
// since fatigue from running affects cycling performance and vice versa.
function unifiedLoad(a){
  if(a.tss) return a.tss; // already has real power-based TSS (cycling)

  var durMin = (a.movingSecs ? a.movingSecs/60 : (a.duration ? parseDurToMin(a.duration) : 0));
  var maxHR = maxHR_();
  var lthr = Math.round(maxHR*0.88);

  if(a.avgHR && durMin){
    // hrTSS: scales duration by intensity relative to threshold HR, using
    // an exponential weighting similar to TrainingPeaks' hrTSS approach
    var hrRatio = a.avgHR/lthr;
    var intensityFactor = Math.min(1.15, hrRatio); // cap runaway values from anomalous HR spikes
    return Math.round(durMin * intensityFactor * intensityFactor * 100/60);
  }

  if(a.rpe && durMin){
    // Foster session-RPE: duration (min) x RPE (1-10), scaled to sit on a
    // comparable numeric range to cycling TSS (roughly /3)
    return Math.round((durMin * a.rpe) / 3);
  }

  return 0;
}

function parseDurToMin(durStr){
  if(!durStr) return 0;
  var parts = String(durStr).split(':').map(Number);
  if(parts.length===3) return parts[0]*60+parts[1]+parts[2]/60;
  if(parts.length===2) return parts[0]+parts[1]/60;
  return parseFloat(durStr)||0;
}

// ===== RACES: single source of truth =====================================
// st.races is the ONE store. getNextRace_() is the single accessor every
// consumer (dashboards, AI Coach) reads, so there is no more fake/hardcoded
// race data anywhere. Legacy st.events entries are folded in once, then
// st.events is retired. No auto-seeded demo race — an empty list stays empty.
var _racesReady=false;
// Parse 'YYYY-MM-DD' (zero-padded OR not) as a LOCAL date. new Date('2026-7-8')
// is invalid and new Date('2026-07-08') is UTC midnight (drifts a day west of
// GMT) — both bugs this avoids.
function parseRaceDate_(s){
  var p=String(s||'').split('-');
  if(p.length===3){
    var dt=new Date(parseInt(p[0],10), parseInt(p[1],10)-1, parseInt(p[2],10));
    return isNaN(dt)?null:dt;
  }
  var d=new Date(s); return isNaN(d)?null:d;
}
// Best-effort sport for legacy/imported races that predate the sport field.
function raceSportGuess_(name){
  var n=' '+String(name||'').toLowerCase()+' ';
  // NOTE: this whole file is served inside one template literal, so regex
  // backslash-escapes get stripped one level — avoid them here (pad with
  // spaces instead of using word boundaries).
  if(/century|fondo|gravel| crit|cyclo| bike | ride |zwift|watopia|kanza| 100 | 50 /.test(n)) return 'bike';
  if(/marathon|half|10k|5k| run | mile |trail|ultra/.test(n)) return 'run';
  return 'other';
}
// Migrate legacy st.events -> st.races and backfill id/sport. Runs once per
// load (guarded) and only persists when it actually changes something.
function migrateRaces_(){
  if(_racesReady && Array.isArray(st.races)) return;
  var changed=false;
  if(!Array.isArray(st.races)){ st.races=[]; changed=true; }
  // Fold legacy st.events into st.races. Key the "already present" check on a
  // NORMALIZED name|calendar-day (same as the dedup below) and include
  // tombstoned (deleted:true) races. Previously this compared dates by exact
  // string, so a soft-deleted race whose tombstone date format differed from
  // the immortal st.events entry (padding / T00:00:00 / unpadded) failed the
  // check and got re-added un-deleted on every reload — silently resurrecting
  // user deletions. Keying on the normalized day + including tombstones makes
  // the fold idempotent, so it no longer matters that st.events=[] can't
  // survive the Firebase union merge.
  var norm_=function(s){ return String(s||'').toLowerCase().replace(/ +/g,' ').trim(); };
  var raceKey_=function(name,date){ var d=parseRaceDate_(date); var dk=d?(d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()):String(date||''); return norm_(name)+'|'+dk; };
  var existingKeys_={};
  st.races.forEach(function(r){ if(r) existingKeys_[raceKey_(r.name,r.date)]=true; });
  if(Array.isArray(st.events) && st.events.length){
    st.events.forEach(function(e){
      if(!e || !e.date) return;
      var ek=raceKey_(e.name,e.date);
      if(existingKeys_[ek]) return;   // present live OR tombstoned — never re-add
      st.races.push({id:e.id||('race-'+Date.now()+'-'+st.races.length),
        name:e.name||'Race', date:e.date, sport:raceSportGuess_(e.name),
        distance:null, goal:(e.type==='goal'?'Goal':'Finish Strong'), target:'', location:'', status:'active'});
      existingKeys_[ek]=true;
      changed=true;
    });
  }
  if(st.events && st.events.length){ st.events=[]; changed=true; } // best-effort retire; harmless now that the fold is idempotent
  st.races.forEach(function(r,i){
    if(!r.id){ r.id='race-'+(r.date||'x')+'-'+i; changed=true; }
    if(!r.sport){ r.sport=raceSportGuess_(r.name); changed=true; }
    if(r.status==null){ r.status='active'; changed=true; }   // status: active | tentative | cancelled
  });
  // Collapse duplicate races (same name + same calendar date) that earlier
  // seeds/migrations left behind — e.g. Grand Rapids Half seeded into both
  // st.races and the old st.events. IMPORTANT: mark the extras deleted:true
  // (a tombstone) rather than splicing them out. A splice does not survive the
  // Firebase merge — the duplicate has its own id, so mergeArrays_ re-unions it
  // from remote on the next sync (which is why the earlier hard dedup "didn't
  // work"). A deleted flag OR-merges to true and sticks. Date is normalized
  // through parseRaceDate_ so format variants (padding / T00:00:00 / unpadded)
  // still count as the same day. No backslash regex (template literal strips it).
  var _seen={};
  st.races.forEach(function(r){
    if(r.deleted) return; // don't resurrect already-tombstoned races
    var d=parseRaceDate_(r.date);
    var dk=d?(d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()):String(r.date||'');
    var k=String(r.name||'').toLowerCase().replace(/ +/g,' ').trim()+'|'+dk;
    if(_seen[k]){ r.deleted=true; changed=true; }   // keep the first, tombstone the rest
    else _seen[k]=true;
  });
  _racesReady=true;
  if(changed){ try{ sv(); }catch(e){} }
}
// All upcoming races (today or later), soonest first, normalized. The _i field
// is the index into st.races so edit/delete can target the exact entry.
// Cancelled races are EXCLUDED by default so they drop out of every countdown,
// taper narrative, and coach premise (Jul 18 report #5). Pass includeCancelled
// to list them (management views render them struck-through so they can be
// restored). status: 'active' | 'tentative' | 'cancelled'.
function upcomingRaces_(includeCancelled){
  migrateRaces_();
  var today=new Date(); today.setHours(0,0,0,0);
  return (st.races||[]).map(function(r,i){
    var d=parseRaceDate_(r.date);
    var daysOut=d?Math.round((d-today)/86400000):null;
    return {id:r.id, name:r.name||'Race', date:r.date, sport:r.sport||'other',
      distance:(r.distance!=null?r.distance:null), goal:r.goal||'Finish Strong',
      target:r.target||'', location:r.location||'', status:r.status||'active', dateObj:d,
      daysOut:daysOut, weeksOut:(daysOut!=null?Math.ceil(daysOut/7):null), _i:i, _deleted:!!r.deleted};
  }).filter(function(x){ return !x._deleted && (includeCancelled || x.status!=='cancelled') && x.dateObj && x.daysOut>=0; })
    .sort(function(a,b){ return a.dateObj-b.dateObj; });
}
// The single accessor: soonest upcoming race, normalized, or null.
function getNextRace_(){
  var up=upcomingRaces_();
  return up.length?up[0]:null;
}
// Kept for older callers; now just ensures the store is migrated.
function ensureEvents(){ migrateRaces_(); }

