function calcMTGT(){
  var wt = nutrWeightLb_(); // lbs — assumed when none is logged; see nutrWeightLb_
  var targets = {
    HIGH: {
      cal: Math.round(wt * 15.5),
      pro: 165,                             // fixed 165g protein
      carb: Math.round(wt * 3.0),
      fat: 0
    },
    MOD: {
      cal: Math.round(wt * 13.5),
      pro: 165,                             // fixed 165g protein
      carb: Math.round(wt * 2.0),
      fat: 0
    },
    LOW: {
      cal: Math.round(wt * 12.0),
      pro: 165,                             // fixed 165g protein
      carb: Math.round(wt * 1.0),
      fat: 0
    }
  };
  // Fill fat from remaining calories (fat = 9 cal/g, protein = 4, carb = 4)
  ['HIGH','MOD','LOW'].forEach(function(t){
    var usedCal = targets[t].pro*4 + targets[t].carb*4;
    targets[t].fat = Math.max(30, Math.round((targets[t].cal - usedCal)/9));
    // Recalc cal from macros for accuracy
    targets[t].cal = targets[t].pro*4 + targets[t].carb*4 + targets[t].fat*9;
  });
  return targets;
}
