// ONE builder, both surfaces. Desktop renders it into ds-content beside the sidebar; mobile puts
// the same string in a full-screen sheet. Two renderers reading one function is the only way the
// two stay identical — see the desktop/mobile drift note.
function _lgHTML_(){
  // A selected season REPLACES the page body. Same shape as the Athletic Life month selection: one
  // module-level handle, set it and repaint, rather than a second renderer that could drift.
  if(_LG_SEL){
    try{ return _lgSeasonDetailHTML_(); }
    catch(e){ try{ console.error('[legacy-season]', e&&e.message); }catch(_e){}
      _LG_SEL=null; /* fall through to the rails rather than showing a blank page */ }
  }
  var ICO_BIKE='<circle cx="5.5" cy="17.5" r="3.5"/><circle cx="18.5" cy="17.5" r="3.5"/><path d="M15 6h3l2.5 6.5M5.5 17.5l4-9h5l3.5 9"/>';
  var ICO_RUN='<circle cx="13" cy="4" r="1.6"/><path d="M7 20l3-6 3 2 1-5 3 3h2"/><path d="M9 9l4-2 3 3"/>';

  // ---- CYCLING ----
  // Through _lgRowsFor_, not an inline call, so the rail and the season detail are the SAME array.
  var cyc=_lgRowsFor_('cyc');
  var cycFirst=cyc.length?cyc[0].date:null;
  var cent=cyc.filter(function(r){ return r.mi>=100; });
  var cycProv='';
  if(cycFirst){
    cycProv='First recorded ride <b style="color:#fff">'+cycFirst+'</b>'
      +(cent.length?(' &middot; <b style="color:#fff">'+cent.length+'</b> century ride'+(cent.length===1?'':'s')+', first '+cent[0].date):'')
      +'<br>Dated from the earliest ride still in the library, not a claim about when riding began.';
  }
  var H=_lgSummaryPanel_('Cycling','Lifetime totals from Strava, server-side.',ICO_BIKE,
        '#a78bfa', _lgCycTiles_(), cycProv);
  H+=_lgSeasonsPanel_('Cycling','#a78bfa',_lgByYear_(cyc,_LG_CYC_FROM,null),
        'Ranked by miles. Only '+_LG_CYC_FROM+' onward &mdash; the library holds no cycling data at all for 2018, 2019 and 2021, so earlier years cannot be compared honestly.',
        true, cyc, 'cyc');

  // ---- RUNNING ----
  if(!_lgRunsPrimed_()){
    _lgAwaitPrime_();
    return H+_lgWaitingHTML_('Running');
  }
  var runs=_lgRuns_();
  var rSorted=runs.slice().sort(function(a,b){ return String(a.date).localeCompare(String(b.date)); });
  var runFirst=rSorted.length?String(rSorted[0].date).slice(0,10):null;
  var mar=runs.filter(function(r){ return (+r.distance||0)>=26; });
  var half=runs.filter(function(r){ return (+r.distance||0)>=13.1; });
  var runProv='';
  if(runFirst){
    runProv='First recorded run <b style="color:#fff">'+runFirst+'</b>'
      +' &middot; <b style="color:#fff">'+mar.length+'</b> marathon'+(mar.length===1?'':'s')
      +' &middot; <b style="color:#fff">'+half.length+'</b> half marathon or longer'
      +'<br>No elevation figure is shown for running: it is absent from the Strava totals and the local values are not believable before 2021.';
  }
  H+=_lgSummaryPanel_('Running','Lifetime totals from Strava, server-side. Hours are local.',ICO_RUN,
        '#fb923c', _lgRunTiles_(), runProv);
  H+=_lgSeasonsPanel_('Running','#fb923c',_lgByYear_(runs,_LG_RUN_FROM,_LG_RUN_TO),
        'Ranked by miles. '+_LG_RUN_FROM+'&ndash;'+_LG_RUN_TO+' &mdash; 2015 is excluded because its recorded pace (21.8 min/mi) is not believable, and later years hold too few runs to rank.',
        false, runs, 'run');

  // ---- ATHLETE DNA (Phase 2) — the power profile only.
  // The full trait set lives in the DNA Insights tab and is NOT re-implemented here; this section
  // renders the one part that is genuinely a chart. Four axes, one shared unit, one computation
  // (_dnaPowerAxes_) shared with the trait text so the two can never disagree.
  H+='<div style="background:var(--d-panel,#14161c);border:1px solid var(--d-edge,rgba(255,255,255,.08));border-radius:16px;padding:17px 19px;margin-bottom:14px">'
    +'<div style="display:flex;align-items:baseline;gap:9px;flex-wrap:wrap">'
    +'<div style="font-size:16px;font-weight:800;color:var(--d-head,#f1f5f9)">Athlete DNA &mdash; power profile</div>'
    +'<div style="font-size:11px;color:#60a5fa;font-weight:700">cycling</div></div>'
    +'<div style="font-size:11.5px;color:var(--d-dim,#8b93a7);margin-top:2px;line-height:1.5">'
    +'Scored against your own curve, never against other athletes &mdash; Strava exposes no ranking to compare with. '
    +'Every duration is measured against your own best at that duration; Climber, Consistency and Explorer are stated in their own units below.</div>'
    +_dnaRadarHTML_()
    +((typeof _dnaOtherTraitsHTML_==='function')?_dnaOtherTraitsHTML_():'')
    +'</div>';
  H+=((typeof _dnaRunPanelHTML_==='function')?_dnaRunPanelHTML_():'');
  H+=((typeof _momHTML_==='function')?_momHTML_():'');
  return H;
}
// Prime the rails once the HTML is in the document. Until layout runs, scrollWidth and clientWidth
