function renameRide(idx){
  idx = rideResolveIdx_(idx);   // accepts a position OR a durable handle
  var r = st.rides[idx]; if(!r) return;
  uiPrompt('Rename this ride', r.name||'Activity', {title:'Rename ride', okText:'Save', placeholder:'Activity name'}).then(function(newName){
    if(newName===null) return;                       // cancelled — no write
    newName = String(newName).trim();
    if(!newName || newName===(r.name||'')) return;    // empty or unchanged — no write
    st.rides[idx].name = newName;
    markRideEdited_(st.rides[idx], ['name']);   // survives Strava/Intervals sync + cross-device
    sv();
    var el = document.getElementById('ride-detail-name');   // present on both surfaces — live title update
    if(el) el.textContent = newName;
    toast('Renamed!');
  });
}

// ─── DESKTOP 3-PANEL ───────────────────────────────────────────────────────
function normDate(d){
  if(!d) return '';
  var p=d.split('-');
  if(p.length===3) return p[0]+'-'+(p[1].length<2?'0'+p[1]:p[1])+'-'+(p[2].length<2?'0'+p[2]:p[2]);
  return d;
}
// Stable per-ride key for manual bike assignments. Mirrors the ride-list
// dedup keys at ~11106/11770: Strava rides use their immutable stravaId;
// non-Strava rides (FIT/TCX/ICU, which have no durable id) fall back to a
// normalized date + rounded distance + moving-seconds/duration composite.
function rideKey(r){
  if(!r) return '';
  if(r.stravaId) return 's'+r.stravaId;
  var dist=r.distance?Math.round(parseFloat(r.distance)):0;
  return 'k:'+normDate(r.date||'')+'_'+dist+'_'+(r.movingSecs||r.duration||'');
}
// Single accessor for a ride/activity's sport, reading BOTH storage conventions:
// recent Strava rides carry only .sportType (CamelCase, e.g. "VirtualRide",
// "WeightTraining", "Swim"); ~232 legacy imports carry only .type (lowercase,
// e.g. "ride", "weight", "swim"). Reading one field alone is blind to half the
// library. Returns the resolved sport as a string ('' when neither is set);
// callers match case-insensitively (so "run"/"Run", "weight"/"WeightTraining"
// both hit). Field-reads for filtering/counting/sorting/coloring route through
// this so no site sees only half the rides.
function rideSport_(r){ if(!r) return ''; var s=(r.sportType!=null&&r.sportType!=='')?r.sportType:(r.type!=null?r.type:''); return String(s); }
// Shared Recent Activity list for both dashboards (showHomeDash + dsShowDashboard).
// All non-deleted rides, deduped by the canonical rideKey(r) — so two distinct
// same-day rides aren't collapsed the way the old 'd'+date+name key did —
// preferring the copy that carries GPS, sorted newest-first. NO sport-type
// filter: every activity type, including VirtualRide, shows.
// Full deduped activity list (the guts of recentRides_ without the slice):
// all non-deleted rides, deduped by canonical rideKey preferring the GPS-bearing
// copy, NO sport-type filter (VirtualRide/Zwift included). This is THE source any
// aggregate that must not undercount virtual rides should read from.
// ---- store_v2 read repoint (migration step 2) ----------------------------
// ROLLBACK IS THIS ONE LINE: set STORE_V2_READS to false and every reader below
// falls back to the untouched st.rides path on the next render. The legacy body
// of allRidesDeduped_ is deliberately NOT modified — only short-circuited — so a
// rollback restores exactly the previous behaviour, not an approximation of it.
var STORE_V2_READS = true;
// The synchronous ride-typed cache. allRidesDeduped_ has ~17 callers that use it
// INLINE inside render functions (var rides=ded||allRidesDeduped_()), so it cannot
// become async without rewriting all of them — which would defeat the one-line
// rollback. Instead primeStoreV2_ fills this once at boot and the accessor reads it
// synchronously. Null means "not primed yet", and the accessor falls through to
// st.rides, so a slow or failed snapshot read degrades to the old behaviour rather
