function _adhLbl_(k){ var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']; var p=String(k).split('-'); return M[((+p[1]||1)-1)]+' '+(+p[2]||1); }
