function aiCardRideAdherence_(){ return _adhCardInner_('RIDE ADHERENCE', (typeof rideAdherenceTrend_==='function')?rideAdherenceTrend_(st,8):[]); }

// ==================== You vs. You — cumulative month-over-month ghost charts ====================
