// ride would be printed, it says so in words instead.
function _pbCost_(p, rate, med, nA){
  nA=nA||'ride';
  if(p.held || !p.hasForm) return '';
  if(p.key==='pwr' || p.key==='np') return '';
  if(p.key==='week'){
    if(!(rate>0)) return '';
    if(med>0 && p.gap<med) return 'Across seven days that is less than one typical '+_pbFmtMi_(med)+' '+nA+' on top of your usual week.';
    return 'Across seven days that is '+_pbFmtMi_(p.gap)+' on top of a typical '+_pbFmtMi_(rate)+' week.';
  }
  var one='One '+nA+' past '+p.recStr+' clears it';
  // Only distance converts against a distance median. Elevation, duration and speed do not, and
  // inventing a conversion for them would be exactly the move this section avoids.
  if(p.key==='dist' && med>0){
    var mult=Math.round(p.recVal/med*10)/10;
    if(mult<=1) return one+' &mdash; inside a typical '+_pbFmtMi_(med)+' '+nA+'.';   // never a sub-1 activity
    return one+' &mdash; about '+mult+'&times; a typical '+_pbFmtMi_(med)+' '+nA+'.';
  }
  return one+'.';
}
// PURE. rides = raw cycling ride records; now = today. rate/med are the trailing-window figures
// _yvyVM_ already computed; they price the gaps and are never recomputed here.
function _pbCompute_(rides, now, rate, med, nA){
  // nA = singular sport noun ('ride'|'run'). The board is shared by both sports; without it the
  // Run tab reads "Fastest Ride" over running data. Defaults to 'ride' for any legacy caller.
  nA=nA||'ride'; var _NA=nA.charAt(0).toUpperCase()+nA.slice(1);
  var era=new Date(now.getFullYear()-_PB_ERA_YEARS, now.getMonth(), now.getDate()); era.setHours(0,0,0,0);
  var form=new Date(now.getTime()-_PB_FORM_DAYS*86400000);
  var all=(rides||[]).map(_pbNorm_).filter(function(x){ return x.t && !isNaN(x.t.getTime()) && x.t>=era && x.t<=now; })
                     .sort(function(a,b){ return a.t-b.t; });
  if(all.length<_PB_MIN_RIDES) return null;

  var pwrEra=0, pwrForm=0, npEra=0, npForm=0;
  all.forEach(function(x){ var inForm=(x.t>=form);
    if(x.pwr!=null){ pwrEra++; if(inForm) pwrForm++; }
    if(x.np!=null){ npEra++; if(inForm) npForm++; } });
  var pwrOk=(pwrEra>=_PB_PWR_MIN_ERA && pwrForm>=_PB_PWR_MIN_FORM);
  var npOk =(npEra >=_PB_PWR_MIN_ERA && npForm >=_PB_PWR_MIN_FORM);

  var SPECS=[
    { key:'dist', label:'Longest '+_NA,  fmt:_pbFmtMi_,  val:function(x){ return x.mi; },   ok:function(x){ return x.mi>0; } },
    { key:'elev', label:'Biggest Climb', fmt:_pbFmtFt_,  val:function(x){ return x.elev; }, ok:function(x){ return x.elev>0; } },
    { key:'time', label:'Longest Time',  fmt:_pbFmtDur_, val:function(x){ return x.sec; },  ok:function(x){ return x.sec>0; } },
    { key:'mph',  label:'Fastest '+_NA,  fmt:_pbFmtMph_, val:function(x){ return x.mph; },
      ok:function(x){ return x.mi>=_PB_FAST_MIN_MI && x.mph>0 && x.mph<_PB_MPH_CEIL; }, qual:_PB_FAST_MIN_MI+' mi minimum' },
    { key:'pwr',  label:'Best Avg Power', fmt:_pbFmtW_,  val:function(x){ return x.pwr; },  ok:function(x){ return x.pwr!=null; }, need:!pwrOk },
    { key:'np',   label:'Best Normalized Power', fmt:_pbFmtW_, val:function(x){ return x.np; }, ok:function(x){ return x.np!=null; }, need:!npOk }
  ];

  var out=[], dropped=0;
  SPECS.forEach(function(sp){
    if(sp.need){ dropped++; return; }
    var q=all.filter(sp.ok);
    if(!q.length) return;
    var sorted=q.slice().sort(function(a,b){ return sp.val(b)-sp.val(a); });
    var rec=sorted[0], runner=sorted[1]||null;
    var inForm=q.filter(function(x){ return x.t>=form; });
    var bestForm=inForm.length?inForm.slice().sort(function(a,b){ return sp.val(b)-sp.val(a); })[0]:null;
    var recV=sp.val(rec), formV=bestForm?sp.val(bestForm):0;
    var held=!!(bestForm && sp.val(bestForm)>=recV);   // the record IS current form
    out.push({ key:sp.key, label:sp.label, qual:sp.qual||'', unit:'',
      recVal:recV, recStr:sp.fmt(recV), recDate:rec.date, recName:rec.name,
      stoodDays:_pbDays_(rec.t, now),
      hasForm:!!bestForm, formVal:formV, formStr:bestForm?sp.fmt(formV):'',
      formDate:bestForm?bestForm.date:'',
      held:held, gap:held?0:(recV-formV), gapStr:held?'':sp.fmt(recV-formV),
      pct:(recV>0)?Math.max(0,Math.min(100,Math.round(formV/recV*100))):0,
      lead:(held&&runner)?(recV-sp.val(runner)):null,
      leadStr:(held&&runner)?sp.fmt(recV-sp.val(runner)):'',
      runnerDate:(held&&runner)?runner.date:'',
      prog:_pbProg_(all, sp.val, sp.ok), fmt:sp.fmt });
  });

  // Biggest week is an aggregate, not a per-ride best, but it takes the identical gap treatment.
  var wAll=_pbRoll7_(all), wForm=_pbRoll7_(all, form);
  if(wAll){
    var wHeld=!!(wForm && wForm.v>=wAll.v-1e-9);
    out.push({ key:'week', label:'Biggest Week', qual:'rolling 7 days', unit:'',
      recVal:wAll.v, recStr:_pbFmtMi_(wAll.v), recDate:wAll.date, recName:'',
      stoodDays:_pbDays_(wAll.t, now),
      hasForm:!!wForm, formVal:wForm?wForm.v:0, formStr:wForm?_pbFmtMi_(wForm.v):'', formDate:wForm?wForm.date:'',
      held:wHeld, gap:wHeld?0:(wAll.v-(wForm?wForm.v:0)), gapStr:wHeld?'':_pbFmtMi_(wAll.v-(wForm?wForm.v:0)),
      pct:(wAll.v>0)?Math.max(0,Math.min(100,Math.round((wForm?wForm.v:0)/wAll.v*100))):0,
      lead:null, leadStr:'', runnerDate:'',
      prog:_pbWeekProg_(all), fmt:_pbFmtMi_ });
  }

  // What the gap COSTS, in terms you can put on a calendar. Not what it is likely to happen:
  // there is no probability here, because a percentage on a single-ride PR prices a choice as if
  // it were a forecast. Everything below comes off rate/med, the same trailing path Month Race and
  // the Regret Simulator use — no second rate is introduced.
  out.forEach(function(p){ p.cost=_pbCost_(p, rate, med, nA); });

  // Closest gap first — the section leads with the record you can actually take this week.
  // Held records sort last: they are the standard, not the target.
  out.sort(function(a,b){
    if(a.held!==b.held) return a.held?1:-1;
    if(a.hasForm!==b.hasForm) return a.hasForm?-1:1;
    var fa=(a.recVal>0)?a.gap/a.recVal:1, fb=(b.recVal>0)?b.gap/b.recVal:1;
    return fa-fb;
  });
  return { recs:out, sinceYear:era.getFullYear(), eraYears:_PB_ERA_YEARS, formDays:_PB_FORM_DAYS,
           nRides:all.length, droppedForCoverage:dropped };
}


// ==================== cross-sport month normalization — per-sport z-score ====================
// The ONE real design question on the All selector: a 200-mile ride month and a 200-mile run month
// are not comparable, because the units lie. Three options were weighed and two rejected:
//   TIME  — sport-neutral and honest, but flattens intensity: four hours of Z2 riding scores the
//           same as four hours of tempo running.
//   TSS   — right in principle, but only 110 of 409 rides carry it and coverage is uneven across
//           sixteen years, so the composite would be shaped by which rides happened to record it.
//   Z-SCORE per sport — each month scored against MIKEY'S OWN history WITHIN that sport, then the
//           per-sport scores averaged. Taken.
//
// Z-score wins because the run years and the ride years barely overlap. He ran for a decade before
// he cycled, so any distance- or time-based composite makes 2015 look like a weak year for a man
// who was running marathons that spring. Scoring within-sport removes the cross-sport unit from the
// problem entirely: a strong run month and a strong ride month both read as "strong for you."
//
// WHAT IS SCORED: monthly miles per sport, z-scored over that sport's RANKABLE months only. Using
// all months would drag both means down toward the sparse tails (ride 2017: 3 activities) and
// inflate every recent month's score for no reason other than that early data is thin.
//
// COMBINING: a month's All score is the MEAN of its per-sport z-scores, over the sports that were
// actually rankable that month. Not a sum — a sum rewards doing two sports over doing one well,
// which would make a mediocre ride+run month outrank an exceptional ride month. The mean asks
// "how good was this month, for you, in whatever you were doing."
var _ZS_MIN_MONTHS=8;   // below this a mean/sd is noise, not a distribution — sport is not scored
function _zsStats_(vals){
  var n=vals.length; if(n<_ZS_MIN_MONTHS) return null;
  var mean=vals.reduce(function(a,b){ return a+b; },0)/n;
  var v=vals.reduce(function(a,b){ return a+(b-mean)*(b-mean); },0)/n;
  var sd=Math.sqrt(v);
  // A zero-spread distribution cannot produce a z-score; every month is identical by definition, so
  // there is nothing to rank and the sport declines rather than dividing by zero.
  if(!(sd>0)) return null;
  return {mean:mean, sd:sd, n:n};
}
// Returns per-month combined scores across sports, or null when nothing can be scored honestly.
function _zsCompute_(){
  var rides=(typeof _storeV2Rides!=='undefined')?_storeV2Rides:null;
  var runs=(typeof _storeV2Runs!=='undefined')?_storeV2Runs:null;
  if(!rides && !runs) return null;                          // unprimed
  var GATE=(typeof STORE_V2_RANKABLE_MIN==='number')?STORE_V2_RANKABLE_MIN:4;
  function perSport(list, noun){
    if(!list || !list.length) return null;
    var mi={}, cnt={};
    list.forEach(function(a){
      var k=String((a&&a.date)||'').slice(0,7); if(k.length!==7) return;
      mi[k]=(mi[k]||0)+(parseFloat(a&&a.distance)||0);
      cnt[k]=(cnt[k]||0)+1;
    });
    // Rankable months only — same gate as everywhere else, read from the shared constant rather
    // than re-declared. This surface does NOT get to invent its own idea of what counts.
    var months=Object.keys(mi).filter(function(k){ return cnt[k]>=GATE; });
    var st=_zsStats_(months.map(function(k){ return mi[k]; }));
    if(!st) return null;
    var z={};
    months.forEach(function(k){ z[k]=(mi[k]-st.mean)/st.sd; });
    return {noun:noun, z:z, mi:mi, months:months, stats:st};
  }
  var parts=[perSport(rides,'ride'), perSport(runs,'run')].filter(Boolean);
  if(!parts.length) return null;
  // Union of every scored month across sports, each carrying the MEAN of whichever sports were
  // rankable that month. A month where only one sport was rankable scores on that sport alone —
  // correct, because the question is how the month went, not how many sports it contained.
  var all={};
  parts.forEach(function(p){
    Object.keys(p.z).forEach(function(k){
      if(!all[k]) all[k]={sum:0, n:0, parts:{}};
      all[k].sum+=p.z[k]; all[k].n++; all[k].parts[p.noun]=Math.round(p.mi[k]*10)/10;
    });
  });
  // Per-month DESCRIPTIVE extras for the surfaces that draw this. Gathered here rather than in the
  // renderer so a chart cannot re-walk the activity lists and quietly disagree with the scores it
  // is drawing. These do NOT affect scoring or rankability — the gate above already decided which
  // months exist; this only describes them. Cross-sport totals, because the month is the unit.
  var extra={};
  [rides||[], runs||[]].forEach(function(list){
    list.forEach(function(a){
      var d=String((a&&a.date)||''); if(d.length<10) return;
      var k=d.slice(0,7); if(!all[k]) return;                 // scored months only
      if(!extra[k]) extra[k]={elev:0, acts:0, byDay:{}, wk:{}};
      var e=extra[k];
      e.elev+=parseFloat((a&&a.elev!=null)?a.elev:(a&&a.elevation))||0;
      e.acts++;
      var dom=parseInt(d.slice(8,10),10)||0;
      if(dom){
        e.byDay[dom]=(e.byDay[dom]||0)+(parseFloat(a&&a.distance)||0);
        // "Active weeks" counted as 7-day blocks from the 1st, not ISO weeks. A calendar week that
        // straddles two months would otherwise let one ride mark a week active in both, which
        // overstates consistency in exactly the months a reader is most likely to check.
        e.wk[Math.floor((dom-1)/7)]=1;
      }
    });
  });
  var rows=Object.keys(all).map(function(k){
    var e=extra[k]||{elev:0, acts:0, byDay:{}, wk:{}};
    var p=k.split('-');
    var dim=new Date(parseInt(p[0],10), parseInt(p[1],10), 0).getDate();
    var totalMi=0; Object.keys(all[k].parts).forEach(function(s){ totalMi+=all[k].parts[s]; });
    return {ym:k, score:all[k].sum/all[k].n, sports:all[k].n, mi:all[k].parts,
            totalMi:Math.round(totalMi*10)/10, elev:Math.round(e.elev), acts:e.acts,
            byDay:e.byDay, daysInMonth:dim,
            activeWeeks:Object.keys(e.wk).length, weeksInMonth:Math.ceil(dim/7)};
  }).sort(function(a,b){ return b.score-a.score; });
  return {rows:rows, sports:parts.map(function(p){ return p.noun; }), scored:rows.length};
}
// Rank one month against the combined distribution. Returns null when the month was not scored —
// same do-not-claim contract as _covFor_: an unscored month gets no position, not position zero.
function _zsRankOf_(ym){
  var g=_zsCompute_(); if(!g) return null;
  for(var i=0;i<g.rows.length;i++) if(g.rows[i].ym===ym) return {rank:i+1, of:g.rows.length, row:g.rows[i], all:g};
  return null;
}


// ==================== Athletic Life — the All view, built on the z-score ====================
// The claim no single-sport view can make. Ride ranks 29 months, run ranks 147, and neither can
// tell him where a month sits in his ATHLETIC LIFE — which is the thing the page is named after.
//
// Deliberately NOT a copy of the ride hero. That surface is built on this-month-vs-last-month, and
// it works because ride is current. This one is a standings board over sixteen years, so it makes
// no this-month claim at all unless the current month actually scored. When it did not, it says so
// once and shows the standings anyway — the history is the point, and hiding it because today is
// quiet would be the same mistake as drawing run's 2026 as a flat line at zero.
// ==================== You vs. You colour tiers ====================
// THREE tiers, and no green anywhere on this page.
//   ORANGE  a genuine best — a career best, an era best, or a month in the top decile of all the
//           months that can be ranked. Orange is the app's signal for "this matters" on every
//           other surface, so it is spent sparingly here on purpose: if every positive were
//           orange, a career best would look like an ordinary good week and the colour would stop
//           meaning anything.
//   BLUE    good — above your own rolling average, ahead of pace, improving. The honest home for
//           most of what used to be green.
//   GREY    baseline — average or below. Neutral, and never a rebuke: this page frames gaps as
//           closable, so the absence of a claim is the point.
// Red survives for genuine negative DIRECTION (behind, falling). It is not a tier.
var _YVY_TOP='#FC4C02', _YVY_TOP_DIM='#c23a00';
var _YVY_GOOD='#60a5fa', _YVY_GOOD_DIM='#3b82f6';
var _YVY_BASE='#64748b', _YVY_BASE_DIM='#2a3341';
var _YVY_DOWN='#ff5c5c';

// ==================== Growth charts — the app-wide rule ====================
// ANYWHERE a visualisation implies progress, comparison over time, or trajectory, it is drawn as
// a LINE. A horizontal pill bar states one magnitude and stops there: it cannot say whether you
// are accelerating, plateauing or falling off, which is the only question those surfaces are ever
// actually asked. Two things compared over time get overlaid cumulative lines showing how each
// got there; one metric's history gets a sparkline.
//
// Pill bars remain CORRECT for categorical breakdowns with no time dimension — zone distribution
// inside a single ride, the fuel split of a single day. The test is whether the reader could ask
// "is this getting better?" If they could, it is a line.
//
// PALETTE. Every chart gets its own identity rather than repeating the page's status colours, and
// every set below was run through the six checks (lightness band, chroma floor, all-pairs CVD
// separation, normal-vision floor, contrast) against the #0e1117 card surface:
//   Month Race      #FC4C02 #64748b #9333ea   worst normal 19.0 · CVD 9.1
//   Year over Year  #0891b2 #8b5cf6 #d97706   worst normal 21.1 · CVD 10.2
//   Month factors   #ec4899 #3b82f6 #d97706   worst normal 20.1 · CVD 6.3
// The factor set sits in the 6-8 CVD band, which is legal ONLY with secondary encoding — it has
// it: those three are small multiples, each in its own titled panel, never overlaid on one axis.
// DO NOT edit a hex here without re-running that check. Both colour defects this work replaced
// looked fine to the author and failed for a reader.
//
// STATUS colours are not categorical and are never spent as a series identity. Personal Bests
// keeps orange-for-held / blue-for-chasing because there the colour means state, not which line.
var _GC_YOY=['#0891b2','#8b5cf6','#d97706'];
var _GC_FACTOR=['#ec4899','#3b82f6','#d97706'];
var _GC_HELD='#FC4C02', _GC_CHASE='#3b82f6';
// THE shared categorical ramp, in fixed order — cyan, violet, amber, rose. FOUR slots, and that
// is not a placeholder: inside the lightness band a dark chart surface allows, four is the most
// that clears all-pairs separation. Five puts lime against amber at deltaE 3.1 under deuteranopia
// and six puts blue against violet at 1.3, which is indistinguishable. Past four the answer is
// small multiples (each series in its own titled panel, where cross-pair separation does not
// apply), never a generated fifth hue.
var _GC_SET=['#0891b2','#8b5cf6','#d97706','#ec4899'];
function _gcHue_(i){ return _GC_SET[((i%_GC_SET.length)+_GC_SET.length)%_GC_SET.length]; }
// Single-series identities. A lone line has no pair to separate from, so it only has to clear the
// lightness band, the chroma floor and 3:1 against the surface — all four below do. They exist so
// each surface reads as its own chart rather than every sparkline in the app being the same blue.
var _GC_MILES='#0d9488';      // Monthly Mileage — teal
var _GC_WKG='#6366f1';        // W/kg toward the Chase — indigo
var _GC_GOAL='#ec4899';       // Goals — rose
var _GC_LOAD='#d97706';       // weekly training load — amber
var _GC_RECOVERY='#0891b2';   // recovery — cyan
// Sparkline: one metric's history in the space of a label. No axes, no grid, no number on any
// point — whatever card this sits in already carries the current value, so the line's only job is
// direction. A single series, so no legend either: the card heading names it.
//
// pts is oldest-first and MAY CONTAIN NULLS. A null is a period with no qualifying activity, and
// it breaks the line rather than being drawn as zero — a quarter you did not ride is not a
// quarter you rode nothing in, and joining across it would draw a decline that never happened.
// Above this many real readings a series is dense enough that the LINE is the shape and dots
// would just be noise. At or below it, every reading is individually meaningful and drawing only
// the line implies a continuity the data does not have - four annual ratios joined corner to corner
// look like a smooth trend rather than four measurements. So on a sparse series every real point is
// marked, and what the reader sees is how much data there actually is.
var _GC_SPARSE_MAX=12;
function _gcSpark_(pts, col, opts){
  opts=opts||{};
  var W=opts.W||160, H=opts.H||36, P=3, iw=W-P*2, ih=H-P*2;
  var vals=(pts||[]).map(function(p){ return (p&&p.v!=null&&isFinite(p.v))?+p.v:null; });
  var real=vals.filter(function(v){ return v!=null; });
  if(real.length<2) return '';                     // one point is not a trajectory
  var lo=Math.min.apply(null,real), hi=Math.max.apply(null,real);
  // A flat series would divide by zero and, worse, would be drawn as a line pinned to the floor.
  // Centre it instead: level IS the reading, and it should look level.
  var flat=(hi-lo)<1e-9;
  var n=vals.length;
  function X(i){ return P + (n>1 ? i/(n-1)*iw : iw/2); }
  function Y(v){ return flat ? (P+ih/2) : (P + ih - (v-lo)/(hi-lo)*ih); }
  // Segments break at nulls. A run of ONE value cannot be a line, but dropping it would silently
  // delete a real measurement from the chart — an isolated quarter between two empty ones is
  // exactly the case a record card needs to show — so it is kept as a dot instead.
  var segs=[], lone=[], cur=[];
  var close=function(){ if(cur.length>1) segs.push(cur); else if(cur.length===1) lone.push(cur[0]); cur=[]; };
  vals.forEach(function(v,i){
    if(v==null){ close(); return; }
    cur.push(X(i).toFixed(1)+' '+Y(v).toFixed(1));
  });
  close();
  var path=segs.map(function(s){ return 'M'+s.join('L'); }).join(' ');
  var loneDots=lone.map(function(p){ var xy=p.split(' ');
    return '<line x1="'+xy[0]+'" y1="'+xy[1]+'" x2="'+xy[0]+'" y2="'+xy[1]+'" stroke="'+col+'"'
      +' stroke-width="4" stroke-linecap="round" vector-effect="non-scaling-stroke"/>'; }).join('');
  // Area wash under the line only where the line is continuous, at the 10% the mark spec allows.
  var wash='';
  if(opts.fill!==false && segs.length===1){
    var f=segs[0];
    wash='<path d="M'+f.join('L')+'L'+f[f.length-1].split(' ')[0]+' '+(H-P)+'L'+f[0].split(' ')[0]+' '+(H-P)+'Z" fill="'+col+'" opacity=".12"/>';
  }
  var dots='';
  // A marker has to survive preserveAspectRatio="none", which scales x and y independently and
  // draws <circle r> as an ellipse (measured 10.2 x 3.8 px, ratio 2.69, on the Signature card).
  // A zero-length segment with a ROUND linecap and a NON-SCALING stroke paints a true circle
  // whose diameter is the stroke width in screen pixels, so it stays round at any stretch.
  var _dot=function(x,y,d,o){
    return '<line x1="'+x+'" y1="'+y+'" x2="'+x+'" y2="'+y+'" stroke="'+col+'" stroke-width="'+d+'"'
      +' stroke-linecap="round" vector-effect="non-scaling-stroke"'+(o?(' opacity="'+o+'"'):'')+'/>';
  };
  // Sparse series: mark every reading, not just the ends. Opt out with markPoints:false.
  var markAll=(opts.markPoints!=null)?!!opts.markPoints:(real.length<=_GC_SPARSE_MAX);
  if(markAll){ vals.forEach(function(v,i){ if(v==null) return;
    dots+=_dot(X(i).toFixed(1), Y(v).toFixed(1), 3.8, '.85'); }); }
  var lastI=-1; for(var i=n-1;i>=0;i--){ if(vals[i]!=null){ lastI=i; break; } }
  if(lastI>=0) dots+=_dot(X(lastI).toFixed(1), Y(vals[lastI]).toFixed(1), 5.2, 0);
  // The peak still gets its own mark, because on these cards the peak IS the record being chased
  // and the reader's eye should find it without reading a label. It was a stroke-only RING, which
  // the round-cap trick cannot draw - so it is a wider, softer halo instead: same job, and round.
  if(opts.markPeak!==false && !flat){
    var pi=vals.indexOf(hi);
    if(pi>=0 && pi!==lastI) dots=_dot(X(pi).toFixed(1), Y(hi).toFixed(1), 8.2, '.32')+dots;
  }
  return '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" role="img" aria-label="'+(opts.aria||'trend')
    +'" style="width:100%;height:'+H+'px;display:block;overflow:visible">'
    +wash+'<path d="'+path+'" fill="none" stroke="'+col+'" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"'
    +' vector-effect="non-scaling-stroke"/>'+loneDots+dots+'</svg>';
}
// The label strip a sparkline needs to be readable: first period, last period, and what the line
// is measured in. Kept OUT of the SVG so preserveAspectRatio="none" cannot stretch the type.
// ---- year scale ----------------------------------------------------------
// The era floor for anything drawn per YEAR. Pre-2024 months do not clear the ride count this page
// ranks on, and the year chart does not get a looser rule than the hero. Inherited unchanged from
// the bar chart this replaced, along with its reason.
var _YOY_ERA_START=2024;
var _YOY_CUMD=[0,31,59,90,120,151,181,212,243,273,304,334];
function _yoyLeap_(y){ return (((y%4===0)&&(y%100!==0))||(y%400===0)); }
function _yoyDaysInYear_(y){ return _yoyLeap_(y)?366:365; }
// Day of year from Y-M-D INTEGERS, not from a Date. Every date in this library is a local calendar
// day (both importers split on 'T'), and routing it through Date parsing is how a ride lands on the
// wrong day in a timezone west of UTC — the one bug class this page cannot afford at day
// resolution, because it would shift a whole year's curve by one.
function _yoyDayOfYear_(y, mo, d){
  if(!(mo>=1 && mo<=12) || !(d>=1 && d<=31)) return 0;
  return _YOY_CUMD[mo-1] + d + ((_yoyLeap_(y) && mo>2) ? 1 : 0);
}
function _gcSparkFoot_(a, b){
  return '<div style="display:flex;justify-content:space-between;gap:8px;margin-top:3px">'
    +'<span style="font-size:9.5px;color:var(--d-dim)">'+a+'</span>'
    +'<span style="font-size:9.5px;color:var(--d-dim)">'+b+'</span></div>';
}
// The whole "value + its history" block a card carries where a progress bar used to sit. One
// helper because this shape now appears on a dozen surfaces, and each of them writing its own is
// how they drift apart.
//   pts  oldest-first [{v,lab}] (nulls allowed)
//   Returns '' when there is no trend to show — the caller keeps its number and says nothing more,
//   which is the honest degrade. Never a flat line through one point.
function _gcTrend_(pts, col, opts){
  opts=opts||{};
  var svg=_gcSpark_(pts||[], col, { aria:opts.aria||'trend', H:opts.H||34, fill:opts.fill, markPeak:opts.markPeak });
  if(!svg) return '';
  var a=opts.from||((pts[0]&&pts[0].lab)||''), b=opts.to||((pts[pts.length-1]&&pts[pts.length-1].lab)||'');
  return '<div style="margin-top:7px">'+svg
    +((a||b)?_gcSparkFoot_(a,b):'')
    +(opts.note?('<div style="font-size:10px;color:var(--d-dim);margin-top:2px">'+opts.note+'</div>'):'')
    +'</div>';
}
// A SCALE, not a bar. Some numbers on these pages are a single scalar with no history behind them
// — a prediction confidence is the share of one projection band that clears a goal, measured once.
// There is no trajectory to draw and inventing one would be worse than a bar. But a filled pill
// still reads as accumulation ("62% of the way there"), which a probability is not. So it is drawn
// as a marker on a labelled 0-100 scale: same information, none of the progress grammar.
function _gcScale_(pct, col, lo, mid, hi){
  var p=Math.max(0, Math.min(100, Math.round(pct||0)));
  return '<div style="margin-top:9px">'
    +'<div style="position:relative;height:12px">'
    +'<div style="position:absolute;left:0;right:0;top:5px;height:2px;border-radius:1px;background:var(--d-raise)"></div>'
    +'<div style="position:absolute;left:50%;top:2px;width:1px;height:8px;background:var(--d-chip)"></div>'
    +'<div style="position:absolute;left:'+p+'%;top:0;transform:translateX(-50%);width:10px;height:10px;border-radius:50%;background:'+col+';border:2px solid var(--d-edge3);box-sizing:content-box"></div>'
    +'</div>'
    +'<div style="display:flex;justify-content:space-between;margin-top:1px">'
    +'<span style="font-size:9.5px;color:var(--d-dim)">'+(lo||'0%')+'</span>'
    +'<span style="font-size:9.5px;color:var(--d-dim)">'+(mid||'even')+'</span>'
    +'<span style="font-size:9.5px;color:var(--d-dim)">'+(hi||'100%')+'</span></div></div>';
}
// A metric's TRAJECTORY with its goal drawn as a dashed reference line where it actually falls
// inside the plotted range. Factored out of the Power-to-Weight card, which established the
// pattern, so the goal cards cannot drift from it: a goal is a line to reach, not a bar to fill,
// and the card must never draw a rule the data does not reach (or claim one it did not draw).
// Compact by design - these live five-across - so no axis footer, just the shape and the rule.
function _goalSpark_(pts, col, goal, opts){
  opts=opts||{};
  var real=(pts||[]).filter(function(p){ return p && p.v!=null && isFinite(p.v); });
  if(real.length<2){
    return '<div style="font-size:9.5px;color:var(--d-dim);line-height:1.4">'
      +(opts.empty||'Not enough history yet to draw a trend.')+'</div>';
  }
  var v=real.map(function(p){ return p.v; });
  var lo=Math.min.apply(null,v), hi=Math.max.apply(null,v);
  var tp=(hi>lo)?((goal-lo)/(hi-lo)):-1;
  var onChart=(isFinite(tp) && tp>=0 && tp<=1);
  var spark=(typeof _gcSpark_==='function')?_gcSpark_(pts, col, { aria:opts.aria||'trend', H:opts.H||30, fill:false, markPeak:false }):'';
  if(!spark) return '';
  var rule=onChart
    ? '<div style="position:absolute;left:0;right:0;top:'+((1-tp)*100).toFixed(1)+'%;height:0;border-top:1.5px dashed #FFB938;opacity:.85;pointer-events:none"></div>'
    : '';
  return '<div style="position:relative">'+spark+rule+'</div>';
}
// Series builders shared by the converted surfaces. Each returns oldest-first [{v,lab}] and each
// returns [] rather than a guess when the log cannot support a line.
function _gcYMD_(d){ return String((d&&d.date)||d||'').slice(0,10); }
function _gcMonLab_(ymd){
  var p=String(ymd).split('-');
  return (_YVY_MON[(+p[1]||1)-1]||'')+' '+(p[0]||'').slice(2);
}
// Daily fitness series (CTL / ATL / TSB) off pmcSeries_, tail-limited. This is the SAME array
// getFitness_ reads its headline from, so a card's sparkline cannot disagree with the number
// printed above it.
// W/kg over time. The weigh-in log supplies the sampling (it is the denser of the two logs) and
// ftpOn_ supplies the FTP that was actually in effect on that date — NOT today's FTP applied
// backwards, which would redraw history every time the athlete retests and turn a weight-loss
// curve into a fake power curve. Capped to the trailing window so a card shows a trend, not a
// decade.
function _gcWkgPts_(days){
  if(typeof st==='undefined' || !st || !Array.isArray(st.weightLog)) return [];
  if(typeof ftpOn_!=='function') return [];
  var cut=null;
  if(days>0){ var d=new Date(); d.setDate(d.getDate()-days); cut=dayKey_(d); }
  var wl=st.weightLog.filter(function(w){
    var v=(w&&w.weight!=null)?parseFloat(w.weight):NaN;
    return w && w.date && isFinite(v) && v>0 && (!cut || String(w.date).slice(0,10)>=cut);
  }).slice().sort(function(a,b){ return String(a.date)<String(b.date)?-1:1; });
  return wl.map(function(w){
    var ymd=_gcYMD_(w), lb=parseFloat(w.weight), ftp=parseInt(ftpOn_(ymd),10)||0;
    var kg=lb/2.20462;
    return { v:(kg>0 && ftp>0)?Math.round(ftp/kg*100)/100:null, lab:_gcMonLab_(ymd) };
  });
}
// Weekly rate series from an array of {t|week, ...} rollups the Trajectory sections already build.
// pick(w) returns the week's value or null; a week with no denominator is a gap, not a zero.
function _gcWeekPts_(weeks, pick, lab){
  return (weeks||[]).map(function(w, i){
    var v=null; try{ v=pick(w); }catch(e){ v=null; }
    return { v:(v!=null && isFinite(v))?v:null, lab:(lab?lab(w,i):('wk '+(i+1))) };
  });
}
function _gcFitPts_(key, days){
  var raw=[]; try{ raw=pmcSeries_()||[]; }catch(e){ raw=[]; }   // same series as the headline
  var n=Math.max(0, raw.length-(days||90));
  var out=[];
  for(var i=n;i<raw.length;i++){
    var p=raw[i], v=(p && p[key]!=null && isFinite(+p[key]))?+p[key]:null;
    out.push({ v:v, lab:_gcMonLab_(_gcYMD_(p)) });
  }
  return out;
}
// THE tier rule. One place decides "genuine best", so the cards, the bars, the rank strip and the
// timeline cannot disagree about which months earn orange. Top decile (always at least the #1
// month), then the upper half, then baseline.
function _yvyTier_(rank, total){
  if(!(total>0) || !(rank>0)) return _YVY_BASE;
  if(rank<=Math.max(1, Math.ceil(total*0.10))) return _YVY_TOP;
  if(rank<=Math.ceil(total*0.50)) return _YVY_GOOD;
  return _YVY_BASE;
}
// ---- Athletic Life dashboard helpers, mapped onto the three tiers above. The names are kept so
// ---- the call sites read the same; only the hues moved.
// _AL_G is the general positive accent (sparklines, factor bars, the top-five dots, links) -> BLUE.
// _AL_AMBER marks the single PEAK month and the "best month ever" label -> ORANGE. Orange is spent
// only where the claim is a genuine best; everything merely good is blue.
var _AL_G=_YVY_GOOD, _AL_G_DIM=_YVY_GOOD_DIM, _AL_TRACK='#1c2130', _AL_BAR=_YVY_BASE_DIM;
var _AL_TEAL=_YVY_GOOD, _AL_AMBER=_YVY_TOP, _AL_COOL=_YVY_BASE;
// Tier is taken from _yvyRankBand_, the same quartile language the ride surfaces already use, so
// "lower half" means the same thing on both pages. The colour is a mapping of that band and
// nothing more — if the band rule ever moves, the colour follows it automatically.
function _alTierBand_(rank, n){
  return (typeof _yvyRankBand_==='function') ? _yvyRankBand_(rank, n)
    : ((n>1) ? (rank/n<=0.25?'top quarter':(rank/n<=0.5?'upper half':(rank/n<=0.75?'lower half':'bottom quarter'))) : 'your only ranked month');
}
// Colour now comes from the shared tier rule rather than from the quartile BAND. The band language
// ("top quarter") still labels the standing in words, but a top-quarter month is not automatically
// a genuine best — only the top decile earns orange. Words and colour answer two different
// questions on purpose, and the tier rule is the single source for the colour half.
function _alTierColor_(rank, n){
  if(!(n>1)) return _YVY_GOOD;                         // single-month case: nothing to grade against
  return _yvyTier_(rank, n);
}
function _alCap_(s){ return String(s).charAt(0).toUpperCase()+String(s).slice(1); }

// ---- Month-handle namespace. A handle here is the bare 'YYYY-MM' string and NOTHING else. It
// ---- deliberately borrows nothing from Fork B — not rideKey, not rideHandle_, not rideRefOf_ —
// ---- because that grammar resolves positionally against st.rides, and this hero is computed off
// ---- the snapshot. This is a parallel vocabulary, not an extension of the ride one.
var _AL_SEL_YM=null;                                      // the selected month, or null = show the #1 default
function _alHandleOf_(row){ return row && row.ym; }        // the handle of a scored-month row IS its ym
// Resolve a handle against the SAME sorted array that produced rank/rankTot. The list is never
// rebuilt: position in g.rows IS the rank, by construction, so index+1 is the rank with no separate
// lookup that could disagree. Returns null for a handle that is not a scored month — the same
// do-not-claim contract used everywhere on this page.
function _alResolveMonth_(ym, g){
  if(!ym || !g || !g.rows) return null;
  for(var i=0;i<g.rows.length;i++) if(g.rows[i].ym===ym) return {row:g.rows[i], rank:i+1, of:g.rows.length};
  return null;
}
// The one selection entry point, wired to both surfaces because both mount through the shared
// aiRenderOverview_(_aiMount) — there is no desktop/mobile split to mirror here. Clicking the
// already-selected month clears the selection and returns to the #1 default, so the strip is a
// toggle rather than a trap. Re-render is the established aiSetTab_ pattern: set state, repaint.
function alSelectMonth_(ym){
  _AL_SEL_YM=(ym && ym===_AL_SEL_YM) ? null : (ym||null);
  try{ if(typeof _aiMount!=='undefined' && _aiMount && typeof aiRenderOverview_==='function') aiRenderOverview_(_aiMount); }catch(e){}
}
function _alFmtYM_(k){ var p=String(k).split('-'); return (_YVY_MON[(+p[1]||1)-1]||'')+' '+p[0]; }
// Percentile position expressed 0-100, where 100 is the best month. Deliberately NOT the raw z:
// a z of +2.4 means nothing to a reader without the distribution, whereas "you were above 97 of
// every 100 of your own months" is the same fact in a unit anyone can hold. The z is still shown
// on the cards, labelled as what it is.
function _alScore100_(rank, n){ return (n>1) ? Math.round((n-rank)/(n-1)*100) : 100; }
function _alTopPct_(rank, n){ return Math.max(1, Math.round(rank/n*100)); }
// The ring takes the TIER colour, not a fixed green. A gauge that reads green at "top 53%" is
// congratulating a middling month, which is the same species of lie as a flat line at zero.
function _alGauge_(pct, col){
  var R=46, C=2*Math.PI*R, off=C*(1-Math.max(0,Math.min(100,pct))/100);
  return '<svg viewBox="0 0 120 120" style="width:118px;height:118px;display:block">'
    +'<circle cx="60" cy="60" r="'+R+'" fill="none" stroke="'+_AL_TRACK+'" stroke-width="9"/>'
    +'<circle cx="60" cy="60" r="'+(R)+'" fill="none" stroke="'+(col||_AL_G)+'" stroke-width="9" stroke-linecap="round"'
    +' stroke-dasharray="'+C.toFixed(1)+'" stroke-dashoffset="'+off.toFixed(1)+'" transform="rotate(-90 60 60)"/>'
    +'<text x="60" y="58" text-anchor="middle" font-size="31" font-weight="800" fill="#f1f5f9">'+Math.round(pct)+'</text>'
    +'<text x="60" y="77" text-anchor="middle" font-size="10" fill="#5b6678">/100</text></svg>';
}
// Cumulative miles across the month, from the real per-day totals. Cumulative rather than per-day
// because the shape then reads as the month's build; a per-day spike chart at this size is noise.
function _alSpark_(r){
  var n=r.daysInMonth||30, run=0, pts=[], mx=0, d;
  for(d=1; d<=n; d++){ run+=(r.byDay&&r.byDay[d])?r.byDay[d]:0; pts.push(run); if(run>mx) mx=run; }
  if(!(mx>0)) return '<div style="height:34px"></div>';
  var W=150, H=34, path='';
  for(d=0; d<pts.length; d++){
    var x=(pts.length>1?(d/(pts.length-1)):0)*(W-2)+1;
    var y=H-1-(pts[d]/mx)*(H-4);
    path+=(d?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)+' ';
  }
  return '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" style="width:100%;height:'+H+'px;display:block">'
    +'<path d="'+path+'" fill="none" stroke="'+_AL_G+'" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/></svg>';
}
// Gold, matching the warm marker the timeline puts on the same month. One peak, one colour, in
// both places a reader might look for it. The card's border and score stay green — the tier is
// still an achievement; it is the SINGULARITY that is warm.
function _alCrown_(){
  return '<svg width="13" height="13" viewBox="0 0 24 24" fill="'+_AL_AMBER+'" style="display:block">'
    +'<path d="M3 8l4.5 3.5L12 5l4.5 6.5L21 8l-1.8 10H4.8L3 8z"/></svg>';
}
function _alCard_(r, i, n, selYM){
  var top=(i===0), isSel=(r.ym===selYM);
  var s100=_alScore100_(i+1, n);
  var mix=[];
  if(r.mi.ride!=null) mix.push(Math.round(r.mi.ride)+' mi ride');
  if(r.mi.run!=null) mix.push(Math.round(r.mi.run)+' mi run');
  // A card is the same month handle as its bar, so it selects too. A selected card takes a white
  // border; otherwise the #1 keeps its green edge and the rest the default.
  // Card edge follows the SAME tier rule as everything else, so a top-five card that is not a
  // top-decile month no longer wears the best-month colour.
  var _tc=_yvyTier_(i+1, n||0);
  var border=isSel?'#f1f5f9':((_tc===_YVY_TOP)?_YVY_TOP_DIM:(_tc===_YVY_GOOD?_YVY_GOOD_DIM:'#1c2130'));
  return '<div onclick="alSelectMonth_(&#39;'+r.ym+'&#39;)" style="flex:0 0 auto;width:186px;background:var(--d-panel);border:1px solid '+border+';border-radius:13px;padding:13px 13px 11px;cursor:pointer">'
    +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:7px">'
    +(top?_alCrown_():'')
    +'<span style="font-size:11px;font-weight:800;color:'+(top?_tc:'#5b6678')+'">#'+(i+1)+'</span>'
    +(top?'<span style="font-size:9.5px;font-weight:800;color:'+_AL_AMBER+';letter-spacing:.04em;text-transform:uppercase">Best month ever</span>':'')
    +'</div>'
    +'<div style="font-size:13.5px;font-weight:800;color:var(--d-head)">'+_alFmtYM_(r.ym)+'</div>'
    +'<div style="display:flex;align-items:baseline;gap:4px;margin-top:5px">'
    +'<span style="font-size:22px;font-weight:800;color:'+_tc+';letter-spacing:-.01em">'+s100+'</span>'
    +'<span style="font-size:11px;color:var(--d-dim)">/100</span></div>'
    +'<div style="font-size:10.5px;color:var(--d-t3);margin-top:2px">'+(r.score>=0?'+':'')+r.score.toFixed(2)+' z vs your average month</div>'
    +'<div style="margin-top:8px">'+_alSpark_(r)+'</div>'
    +'<div style="font-size:10px;color:var(--d-dim);margin-top:4px">'+(mix.join(' &middot; ')||'&nbsp;')+'</div>'
    +'</div>';
}
// A scoped-board card. Leads with the z-score, NOT a re-based /100, on purpose: the z is the same
// number in any window, so the same month never carries two different scores across the two boards
// — the one-number-two-populations trap this page keeps avoiding. The rank badge is explicitly
// "within the era", and the all-time /100 lives only on the all-time cards. Same handle, so it
// selects and repoints the factor panel like every other month.
function _alEraCard_(r, rankInEra, selYM){
  var isSel=(r.ym===selYM);
  var mix=[]; if(r.mi.ride!=null) mix.push(Math.round(r.mi.ride)+' mi ride'); if(r.mi.run!=null) mix.push(Math.round(r.mi.run)+' mi run');
  return '<div onclick="alSelectMonth_(&#39;'+r.ym+'&#39;)" style="flex:0 0 auto;width:150px;background:var(--d-panel);border:1px solid '+(isSel?'#f1f5f9':'#1c2130')+';border-radius:12px;padding:11px 12px;cursor:pointer">'
    +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px"><span style="font-size:11px;font-weight:800;color:'+(rankInEra===1?_YVY_TOP:'#5b6678')+'">#'+rankInEra+'</span>'
    +(rankInEra===1?('<span style="font-size:9px;font-weight:800;color:'+_YVY_TOP+';letter-spacing:.04em;text-transform:uppercase">era best</span>'):'')+'</div>'
    +'<div style="font-size:13px;font-weight:800;color:var(--d-head)">'+_alFmtYM_(r.ym)+'</div>'
    +'<div style="display:flex;align-items:baseline;gap:3px;margin-top:4px"><span style="font-size:18px;font-weight:800;color:'+(rankInEra===1?_YVY_TOP:_YVY_BASE)+';letter-spacing:-.01em">'+(r.score>=0?'+':'')+r.score.toFixed(2)+'</span>'
    +'<span style="font-size:10px;color:var(--d-dim)">z</span></div>'
    +'<div style="margin-top:6px">'+_alSpark_(r)+'</div>'
    +'<div style="font-size:10px;color:var(--d-dim);margin-top:4px">'+(mix.join(' &middot; ')||'&nbsp;')+'</div>'
    +'</div>';
}
// Every scored month in date order. Bar height is the combined z floored at zero for display, which
// is a display choice and nothing else: a below-average month is still a month he trained, and
// drawing it as negative space would read as a hole in the record rather than a quiet month.
//
// MOBILE: the strip scrolls rather than shrinking. 164 bars squeezed into 380px is four device
// pixels each, which is not a chart. A floor of 5px per bar plus horizontal scroll keeps every
// month legible at any width and costs nothing on desktop, where it simply fits.
// peakYM is the all-time #1 and takes a WARM marker while the rest of the top five stay green.
// Without it the peak is just one of five identical dots, and the single best month of sixteen
// years is the one thing on this strip a reader is actually hunting for.
function _alTimeline_(asc, topSet, peakYM, selYM){
  var mx=0; asc.forEach(function(r){ if(r.score>mx) mx=r.score; });
  if(!(mx>0)) mx=1;
  var H=52, bars='', labels='', seen={};
  asc.forEach(function(r){
    var h=Math.max(2, Math.round(Math.max(0,r.score)/mx*H));
    var isTop=!!topSet[r.ym], isPeak=(r.ym===peakYM), isSel=(r.ym===selYM);
    var col=isPeak?_AL_AMBER:(isTop?_AL_G:_AL_BAR);
    // Every bar drawn IS a scored month (asc is g.rows) — so every bar is a legitimate target and an
    // unscored month is never rendered as clickable. Selection is shown by a white ring on the bar
    // and a white marker above it, distinct from the amber peak and green top-five dots.
    var marker=isSel
      ? '<span style="width:7px;height:7px;border-radius:50%;border:1.5px solid var(--d-head);box-sizing:border-box;margin-bottom:'+(isTop?1:3)+'px"></span>'
      : (isTop?('<span style="width:'+(isPeak?9:7)+'px;height:'+(isPeak?9:7)+'px;border-radius:50%;background:'+(isPeak?_AL_AMBER:_AL_G)+';margin-bottom:'+(isPeak?2:3)+'px"></span>')
             :('<span style="height:10px"></span>'));
    bars+='<div onclick="alSelectMonth_(&#39;'+r.ym+'&#39;)" title="'+_alFmtYM_(r.ym)+' &middot; z '+(r.score>=0?'+':'')+r.score.toFixed(2)+(isPeak?' &middot; your best month':'')+'"'
      +' style="flex:1;min-width:5px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;cursor:pointer">'
      +marker
      +'<span style="width:100%;height:'+h+'px;background:'+col+';border-radius:2px 2px 0 0'+(isSel?';box-shadow:0 0 0 1.5px var(--d-head)':'')+'"></span></div>';
    var y=String(r.ym).slice(0,4), first=!seen[y]; if(first) seen[y]=1;
    labels+='<div style="flex:1;min-width:5px;position:relative;height:13px">'
      +(first?('<span style="position:absolute;left:0;top:0;font-size:9px;color:var(--d-dim);white-space:nowrap">'+y+'</span>'):'')
      +'</div>';
  });
  var minW=Math.max(560, asc.length*7);
  return '<div style="overflow-x:auto;padding-bottom:2px">'
    +'<div style="min-width:'+minW+'px">'
    +'<div style="display:flex;align-items:flex-end;gap:1px;height:'+(H+12)+'px">'+bars+'</div>'
    +'<div style="display:flex;gap:1px;margin-top:3px">'+labels+'</div>'
    +'</div></div>';
}
// Volume, consistency, climbing. These three only. Each bar is scaled against his own best scored
// month on that factor, so the length means "how close to your ceiling", not a share of some
// invented target. There is no fitness curve here on purpose: CTL/ATL need TSS, which only about
// a quarter of the rides carry, and a smooth line drawn through that would be invention.
// One hue per factor, so the three read as three things at a glance rather than as one bar drawn
// three times. The hue identifies the factor and carries no ranking — length is the only quantity
// here, and a reader should not have to check the label to know which bar is which.
// SMALL MULTIPLES, one per factor, each a sparkline of that factor MONTH BY MONTH across every
