function _segFmtT_(sec){ sec=Math.round(+sec||0); var h=Math.floor(sec/3600), m=Math.floor((sec%3600)/60), s=sec%60; return (h>0?(h+':'+('0'+m).slice(-2)):(''+m))+':'+('0'+s).slice(-2); }
