function _dnaSecLabel_(s){ return s<60?(s+'s'):(s%3600===0?((s/3600)+'h'):((s/60)+'m')); }
// ---- RUNNING DNA -----------------------------------------------------------------------------
// An explicitly HISTORICAL profile. Running is currently dormant — 3 runs and 10 miles in the last
