  { label:'5K',       mi:3.107,  col:'#fb923c' },
  { label:'10K',      mi:6.214,  col:'#facc15' },
  { label:'Half',     mi:13.109, col:'#4ade80' },
  { label:'Marathon', mi:26.219, col:'#38bdf8' }
