    +_trjRowProj_('','FTP',fFit,null,'up','W',0)
    +_trjRowProj_('','Weight',wFit,null,'down',' lbs',1)
    +_trjRowProj_('','CTL (fitness)',cFit,null,'up','',0)
    +'<div style="font-size:10.5px;color:var(--d-dim);line-height:1.45;margin-top:9px">'
