function aiRenderTab_(tab, ded){
  if(tab==='segattack') return _aiSafe_('SegAttack', function(){return aiRenderSegAttack_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Segment Attack — render error.</div>';
  if(tab==='seglib') return _aiSafe_('SegLibrary', function(){return aiRenderSegLibrary_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Segment Library — render error.</div>';
  // The 'changed' dispatch went with the nav entry. An unreachable tab must not keep a live
  // renderer: the pair is what the "every nav tab has a dispatch" invariant checks, and leaving a
  // dispatch behind a removed tab is the same drift in the opposite direction.
  // Wrapped like every sibling. Trends guards its own sub-computations (_trStory_, _trDrivers_,
  // _trPredictions_, _trWatchDay_) but the dispatch itself was bare, so a throw anywhere in the
  // rest of the body — coverage, the PMC block, chart assembly — escaped aiRenderTab_ and took the
  // whole Athlete Intelligence page down instead of degrading to one tab saying it failed.
  if(tab==='trends') return _aiSafe_('Trends', function(){return aiRenderTrends_(ded);}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Trends — render error.</div>';
  if(tab==='racing') return _aiSafe_('Racing', function(){return aiRenderRacing_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">You vs. You — render error.</div>';
  if(tab==='milestones') return _aiSafe_('Milestones', function(){return aiRenderMilestones_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Milestones — render error.</div>';
  if(tab==='records') return _aiSafe_('Records', function(){return aiRenderRecords_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Records — render error.</div>';
  if(tab==='ghost') return _aiSafe_('GhostTab', function(){return aiRenderGhost_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Ghost Rival \u2014 render error.</div>';
  if(tab==='almost') return _aiSafe_('AlmostTab', function(){return aiRenderAlmost_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Almost Board \u2014 render error.</div>';
  if(tab==='dna') return _aiSafe_('DNAtab', function(){return aiRenderDNA_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">DNA — render error.</div>';
  if(tab==='trajectory') return _aiSafe_('Trajectory', function(){return aiRenderTrajectory_();}) || '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Trajectory — render error.</div>';
  if(tab!=='overview'){
    var name=(AI_TABS.filter(function(t){return t[0]===tab;})[0]||['','This tab'])[1];
    return '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">'+aiEsc_(name)+' — coming soon.</div>';
  }
  // ---- OVERVIEW v1: HERO + TODAY'S FOCUS ------------------------------------------------------
  // The page's problem was eleven cards shouting at equal volume with no read order. These two sit
  // ABOVE the grid and answer "what matters right now" before anything else competes.
  //
  // NO composite score. The mockup's "Athlete IQ 72" is deliberately absent: it would blend inputs
  // that are not independent (CTL already contains consistency and volume) with weights nothing can
  // validate. Same objection that killed the blended Momentum score, same answer.
  //
  // Everything here reuses an existing single source — _momData_ for direction, getReadiness_ for
  // readiness, _msCatalog_ for the milestone. Nothing is recomputed, so the hero cannot disagree
  // with the cards below it.
  // ---- OVERVIEW v3: SIX SECTIONS -------------------------------------------------------------
  // 1 What Matters Right Now (decision hierarchy) + Today/Next
  // 2 Current State      3 Your Goals      4 Performance
  // 5 Athlete DNA + AI Coach              6 Recent Signals
  //
  // v2's Momentum, Highlights, Opportunity, Legacy and Story builders are intentionally no longer
  // called from Overview. They were not deleted - Trends, Records and the DNA tab own that content -
  // but nothing on this page renders them any more, which is the whole point of the trim.
  var hero=_aiSafe_('OvwHero', function(){return _ovwHeroHTML_();});
  var focus=_aiSafe_('TodaysFocus', function(){return _ovFocusHTML_();});
  var cur=_aiSafe_('OvwCurrentState', function(){return _ovwCurrentStateHTML_();});
  var goals=_aiSafe_('OvwGoals', function(){return _ovwGoalsHTML_();});
  var perf=_aiSafe_('OvwPerf', function(){return _ovwPerfHTML_();});
  // The REAL power radar, not the mockup's invented 6-axis 0-100 model. This is a fabrication
  // fix for one card; it is NOT the DNA Insights feature, which is still unbuilt.
  //
  // It said "4-axis" until Aug 11 2026 and no longer does: _dnaRadarHTML_ draws the TEN-duration
  // power curve whenever six or more durations carry data, and falls back to the four ranked
  // trait bars only below that. Ten spokes is the safer shape anyway - each is scored against
  // your own best AT THAT DURATION, so a 782 W sprint cannot dwarf a 265 W hour, which is
  // exactly the flaw that got the four-axis version demoted from a radar to bars.
  var dna=_aiSafe_('OvwDNA', function(){
    var r=(typeof _dnaRadarHTML_==='function')?_dnaRadarHTML_():'';
    if(!r) return '';
    return _ovwCard_(_ovwLbl_('Athlete DNA','<span onclick="aiSetTab_(&#39;dna&#39;)" style="font-size:11px;color:var(--d-accent,#fc5200);cursor:pointer">Explore DNA</span>')+r);
  });
  var coach=_aiSafe_('OvwCoach', function(){return _ovwCoachHTML_();});
  var signals=_aiSafe_('OvwSignals', function(){return _ovwSignalsHTML_();});
  // GRID TRIM. The card grid under the hero rows is GONE — Overview is the hero clusters, the three
  // context cards, and Your Athletic Story. Everything that has a home of its own lives there now
  // instead of being duplicated here at equal volume:
  //   Athlete DNA                      -> DNA Insights tab (aiRenderDNA_)
  //   Strength Adherence / Progression,
  //   Ride Adherence, Zones            -> Trends tab (aiRenderTrends_)
  //   Records                          -> Records tab (aiRenderRecords_)
  //   Weight                           -> folded INTO the Legacy card (_ovLegacyHTML_). It was the
  //                  last tile left in the grid, sitting alone in a three-column row beside two
  //                  empty cells. Folded rather than widened: a lone full-width bodyweight card
  //                  would have given one number the visual weight of a whole row.
  // DROPPED outright, not moved:
  //   Watchlist    — its annual-mileage line reads st.yearlyMileageGoal, a second goal system beside
  //                  the approved Century/Everest targets. (The mileage FIGURE was a separate bug and
  //                  is fixed at source in _ytdCycMi_ / _athleteStatsStale_, because the same number
  //                  still feeds the mobile YTD ring and the coach's day state.)
  //   What Changed — redundant with Momentum and Highlights in the hero above.
  if(!hero && !focus && !cur && !goals && !perf && !dna && !coach && !signals){
    return '<div style="padding:60px 20px;text-align:center;color:var(--d-dim);font-size:14px">Nothing to show yet.</div>';
  }
  // LAYOUT - six sections, in the order they should be read.
  //   1  hero (What Matters Right Now) beside Today/Next
  //   2  Current State, full width - it is a strip, not a card
  //   3  Your Goals beside Performance
  //   4  Athlete DNA beside AI Coach
  //   5  Recent Signals, full width
  // Every row collapses to one column under 860px so mobile reads top to bottom in the same order
  // of importance rather than in whatever order the grid happened to wrap.
  var row=function(cols, tmpl){
    var live=cols.filter(function(c){ return c; });
    if(!live.length) return '';
    var t=(live.length===cols.length)?tmpl:('repeat('+live.length+', minmax(0,1fr))');
    return '<div class="ov-row" style="display:grid;grid-template-columns:'+t+';gap:10px;margin-bottom:10px">'+live.join('')+'</div>';
  };
  var html='<style>@media(max-width:860px){.ov-row{grid-template-columns:1fr !important}.ov-cols{flex-direction:column !important}}</style>';
  // COLUMN FLOW, NOT ROWS. Pairing by row meant a card could not start until the TALLEST card in
  // the row above it had finished: Performance sat waiting on DNA even though Goals, directly above
  // it, had ended hundreds of pixels earlier. Two independent columns remove the barrier - each one
  // stacks on its own height, so Performance slides straight up under Goals and AI Coach does the
  // same under DNA.
  //
  // Deliberately two flex COLUMNS rather than CSS multi-column or a masonry grid: those reflow by
  // available space and would reorder the cards on a width change, and the reading order here is
  // meaningful. This keeps each card in a named column.
  var col=function(cards, grow){
    var live=cards.filter(function(c){ return c; });
    if(!live.length) return '';
    return '<div style="flex:'+grow+' 1 0;min-width:0;display:flex;flex-direction:column;gap:10px">'+live.join('')+'</div>';
  };
  html+=row([hero, focus], 'minmax(0,1.55fr) minmax(0,1fr)');
  if(cur) html+='<div style="margin-bottom:10px">'+cur+'</div>';
  // The five cards go out as ONE ordered list and _balCols_ assigns them to columns from their
  // measured heights after mount. The order here is the page's authored section order - Goals,
  // DNA, Performance, Coach, Signals - which is what a reader sees top to bottom.
  var _balCards=[goals, dna, perf, coach, signals].filter(function(c){ return c; });
  if(_balCards.length){
    html+='<div class="ov-bal" style="margin-bottom:10px">'+_balCards.join('')+'</div>';
  }
  // Nothing is emitted below the columns now - Signals lives inside colL. If it were left here
  // as well it would render twice.
  return html;
}
// ---- Athlete Status hero ----------------------------------------------------------------------
// Direction, readiness and the next milestone — the three things that answer "where am I and what
// is today". Each comes from the app's single source for that fact, never a local re-derivation.
// ============================================================================================
// OVERVIEW v3 - six sections, down from v2's eight.
//
// Cut outright and NOT re-added here: the Legacy timeline, Momentum's full CTL/ATL/TSB chart (the
// values live in Current State; the chart stays on Trends), and the six-tile Training Ecosystem
// grid. Weather / Nutrition / Recovery / Gear / Plan keep their own pages and feed the decision
// hierarchy without owning an Overview card.
//
// Every section renders an em-dash rather than a number it cannot stand behind.
// ============================================================================================
// CARDS DO NOT STRETCH. Stretching to the row and centring was tried first and looked worse: DNA is
// roughly twice the height of Goals, not comparable to it, so centring split one enormous gap into
// two - blank panel above the content AND below it. The empty region was visible because the CARD
// BACKGROUND was being stretched behind it.
//
// A card that simply ends where its content ends has no hole in it at all. The row is still as tall
// as its tallest card, but the space beside a short one is page background rather than an empty
// panel, which reads as layout instead of as an unfinished card.
function _ovwCard_(inner, pad){
  return '<div style="background:var(--d-panel);border:1px solid var(--d-edge);border-radius:14px;padding:'+(pad||'14px 16px')+';min-width:0;align-self:start">'+inner+'</div>';
}
function _ovwLbl_(t, right){
  return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:11px">'
    +'<span style="font-size:10px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:var(--d-dim)">'+t+'</span>'
    +(right||'')+'</div>';
}
function _ovwDash_(){ return '<span style="color:var(--d-dim)">&mdash;</span>'; }
function _ovwDelta_(v, goodUp){
  if(v==null || !isFinite(v) || v===0) return '';
  var up=v>0, good=(goodUp===false)?!up:up;
  var col=good?'#4ade80':'#f87171';
  return '<span style="font-size:11px;font-weight:700;color:'+col+';margin-left:5px">'+(up?'+':'')+(Math.round(v*10)/10)+'</span>';
}

// ---- 1. WHAT MATTERS RIGHT NOW ---------------------------------------------------------------
// The hero is whatever the decision hierarchy decided, rendered as-is. It carries the tier and the
// rule key in the DOM so a screenshot can always be traced back to the rule that produced it -
// this page's whole problem historically was a claim nobody could source.
function _ovwHeroHTML_(){
  var hit=null;
  try{ hit=ovwEvaluate_(); }catch(e){ return ''; }
  if(!hit) return '';
  var quiet=(hit.tier===6);
  var accent=quiet?'#4ade80':(hit.tier<=2?'#f87171':(hit.tier<=3?'#f59e0b':'#4ade80'));
  // align-self:start for the same reason _ovwCard_ carries it: this card is usually much shorter
  // than Today's Focus beside it (a headline, a sentence and a stat row against three bullets), and
  // a stretched border left a large empty block under the content. The row is still as tall as its
  // tallest card; this one just stops where it ends.
  var H='<div data-ovw-tier="'+hit.tier+'" data-ovw-key="'+aiEsc_(hit.key)+'" style="background:var(--d-panel);border:1px solid '+accent+'55;border-left:3px solid '+accent+';border-radius:14px;padding:16px 18px;align-self:start">';
  H+='<div style="font-size:10px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:'+accent+';margin-bottom:8px">What matters right now</div>';
  H+='<div style="font-size:20px;font-weight:800;color:var(--d-head);line-height:1.25;letter-spacing:-.01em">'+aiEsc_(hit.title)+'</div>';
  if(hit.body) H+='<div style="font-size:13px;color:var(--d-t3);margin-top:7px;line-height:1.5">'+aiEsc_(hit.body)+'</div>';
  if(hit.facts && hit.facts.length){
    H+='<div style="display:flex;gap:18px;flex-wrap:wrap;margin-top:13px;padding-top:12px;border-top:1px solid var(--d-edge)">';
    hit.facts.forEach(function(f){
      H+='<div style="min-width:0"><div style="font-size:10px;color:var(--d-dim);text-transform:uppercase;letter-spacing:.05em">'+aiEsc_(f.label)+'</div>'
        +'<div style="font-size:15px;font-weight:700;color:var(--d-head);margin-top:2px">'+aiEsc_(String(f.value))+'</div></div>';
    });
    H+='</div>';
  }
  // A SECOND SIGNAL, when there genuinely is one. The ladder stops at the first hit, but lower
  // tiers are often true as well - today tier 3 wins while tiers 4 and 5 both also fire. Naming the
  // runner-up uses the space under a short hero without inventing anything: it is a rule that
  // evaluated true against real data and was outranked, not filler.
  if(hit.also){
    H+='<div style="margin-top:13px;padding-top:11px;border-top:1px solid var(--d-edge)">'
      +'<div style="font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--d-dim);margin-bottom:4px">Also true today</div>'
      +'<div style="font-size:13px;font-weight:600;color:var(--d-t3);line-height:1.4">'+aiEsc_(hit.also.title)+'</div>';
    if(hit.also.facts && hit.also.facts.length){
      H+='<div style="font-size:11px;color:var(--d-dim);margin-top:3px">'
        +aiEsc_(hit.also.facts.map(function(f){ return f.label+' '+f.value; }).join('  ·  '))+'</div>';
    }
    H+='</div>';
  }
  return H+'</div>';
}

// ---- 2. CURRENT STATE ------------------------------------------------------------------------
// FITNESS IS CTL. They are the same number and there is exactly one cell for them. The mockup
// showed "Fitness (CTL) 181" beside "CTL 57" as two separate metrics on one strip - 181 was the
// FTP, mislabelled. Every value here comes from getFitness_, the single fitness source, and the
// 7-day deltas come from the same st.fitSeries the chart on Trends reads.
function _ovwCurrentStateHTML_(){
  var f=null; try{ f=getFitness_(); }catch(e){}
  var ser=[]; try{ ser=(st.fitSeries||[]).slice().sort(function(a,b){ return String(a.date).slice(0,10).localeCompare(String(b.date).slice(0,10)); }); }catch(e){}
  var wk=(ser.length>=8)?ser[ser.length-8]:null;
  var ftp=parseInt((typeof st!=='undefined'&&st.ftp)||0,10)||null;
  // TAP TO LEARN. Each cell names the METRIC_TEACH entry it explains. Both halves of this
  // already existed - the entries (ctl/atl/tsb/ftp, with their aka, one-liner, ranges and note)
  // and the document-level [data-metric-teach] listener that opens the shared panel. The v3
  // rebuild simply stopped emitting the attribute, so there was nothing for the listener to
  // match and the explanations silently disappeared with the old layout.
  var cells=[
    { k:'Fitness (CTL)', teach:'ctl', v:(f&&f.loaded)?f.ctl:null, d:(f&&f.loaded&&wk)?(f.ctl-wk.ctl):null, up:true },
    { k:'Fatigue (ATL)', teach:'atl', v:(f&&f.loaded)?f.atl:null, d:(f&&f.loaded&&wk)?(f.atl-wk.atl):null, up:false },
    { k:'Form (TSB)',    teach:'tsb', v:(f&&f.loaded)?f.tsb:null, d:(f&&f.loaded&&wk)?(f.tsb-wk.tsb):null, up:true },
    { k:'FTP',           teach:'ftp', v:ftp, unit:' W', d:null, up:true }
  ];
  var H=_ovwLbl_('Current state', (f&&f.stale)?('<span style="font-size:10px;color:#f59e0b">'+aiEsc_(f.ageLabel||'stale')+'</span>'):'');
  H+='<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px">';
  cells.forEach(function(c){
    // A dotted underline on the LABEL is the app's existing 'this explains itself' affordance
    // (see the inline glossary term); the whole tile is the target so it is tappable on a phone.
    var _tk=c.teach?(' data-metric-teach="'+c.teach+'" role="button" tabindex="0" title="Tap to learn what this means" style="min-width:0;cursor:pointer"'):' style="min-width:0"';
    H+='<div'+_tk+'>'
      +'<div style="font-size:10.5px;color:var(--d-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis'
        +(c.teach?';border-bottom:1px dotted var(--d-edge3,rgba(255,255,255,.25));display:inline-block':'')+'">'+c.k+'</div>'
      +'<div style="display:flex;align-items:baseline;margin-top:3px">'
      +'<span style="font-size:22px;font-weight:800;color:var(--d-head);line-height:1">'+((c.v==null)?_ovwDash_():(c.v+(c.unit||'')))+'</span>'
      +_ovwDelta_(c.d, c.up)+'</div>'
      +'<div style="font-size:9.5px;color:var(--d-dim);margin-top:3px">'+((c.d==null)?'&nbsp;':'vs 7 days ago')+'</div></div>';
  });
  H+='</div>';
  // RECOVERY LIVES HERE NOW, not on the Dashboard. It is diagnostic rather than plan-actionable -
  // the Dashboard keeps Readiness, which is the daily verdict you act on - and this is the section
  // that already answers "where am I right now", so the two readings sit together instead of one
  // being a card of its own on a page with no room for it.
  //
  // The composite comes from _recoveryNow_, so the number cannot diverge from wherever else it is
  // read, and the entry point survives the move: openRecoveryEditor_ is global and the label links
  // straight to it, which is what the Dashboard card's Edit affordance did.
  try{
    var rec=(typeof _recoveryNow_==='function')?_recoveryNow_():null;
    if(rec){
      H+='<div style="height:1px;background:var(--d-edge);margin:14px 0 12px"></div>';
      H+='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'
        +'<span style="font-size:11px;font-weight:700;color:var(--d-dim);text-transform:uppercase;letter-spacing:.08em">Recovery</span>'
        +'<span onclick="if(window.openRecoveryEditor_)openRecoveryEditor_()" style="font-size:11px;font-weight:600;color:var(--c-green);cursor:pointer">Log today</span>'
        +'</div>';
      if(!rec.have){
        // ABSENT SAYS ABSENT. No substitute number, no readiness verdict wearing a recovery label.
        H+='<div style="font-size:12px;color:var(--d-dim);line-height:1.5">No HRV or resting heart rate for today. '
          +'Recovery is a composite of those two against your own baseline, so it needs both before it can say anything.</div>';
      } else {
        var rcells=[
          // THE PERCENT SIGN IS LOAD-BEARING. HRV+RHR against a baseline genuinely is a 0-100
          // composite of two measurements, so it reads as a percentage - unlike a form-readiness
          // BAND, which is one input scored into a range and must never be dressed as one. That
          // distinction is why the old Recovery card had two modes and why only this one moved.
          { k:'Recovery', v:rec.score, unit:'%', col:rec.col, sub:rec.label },
          { k:'HRV',      v:rec.hrv,   unit:' ms', col:'var(--d-head)', sub:(rec.bHRV?('baseline '+Math.round(rec.bHRV)+' ms'):'no baseline yet') },
          { k:'Resting HR', v:rec.rhr, unit:' bpm', col:'var(--d-head)', sub:(rec.bRHR?('baseline '+Math.round(rec.bRHR)+' bpm'):'no baseline yet') }
        ];
        H+='<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px">';
        rcells.forEach(function(c){
          H+='<div><div style="font-size:10.5px;color:var(--d-dim)">'+c.k+'</div>'
            +'<div style="font-size:22px;font-weight:800;color:'+c.col+';line-height:1;margin-top:3px">'+c.v+c.unit+'</div>'
            +'<div style="font-size:9.5px;color:var(--d-dim);margin-top:3px">'+c.sub+'</div></div>';
        });
        H+='</div>';
        // THE BASELINE'S SIZE, STATED. "vs your baseline" with two days behind it and with
        // twenty-eight are different claims, and the score alone cannot tell them apart.
        H+='<div style="font-size:9.5px;color:var(--d-dim);margin-top:9px">'
          +(rec.baselineN?('Scored against your '+rec.baselineN+'-day baseline'):'Building a baseline - the score is provisional until there is history behind it')
          +(rec.src?(' &middot; '+rec.src):'')+'</div>';
      }
    }
  }catch(e){}
  return _ovwCard_(H);
}

// Goal TRAJECTORIES. A bar says where you are; a line says whether you are pacing ahead or behind,
// which is the useful question for a goal that accumulates over time. This is also the app's own
// standing rule - progress is a line, never a bar - which the first version of this card broke.
//
// EVERY SERIES COMES FROM THE EXISTING SOURCE, never a parallel computation. CTL is st.fitSeries
// (what Trends charts), FTP is st.ftpHistory (what the FTP surfaces read). The two mileage series
// are derived from the same deduped ride library the rest of the page counts, and the test asserts
// the LAST point of each equals the current value already shown beside it - so the line and the
// number cannot drift apart, which is the exact failure this page kept producing today.
function _ovwGoalSeries_(kind){
  try{
    if(kind==='ctl'){
      return (st.fitSeries||[]).slice()
        .sort(function(a,b){ return _ovwDay_(a.date).localeCompare(_ovwDay_(b.date)); })
        .slice(-60).map(function(x){ return { v:+x.ctl }; })
        .filter(function(x){ return isFinite(x.v); });
    }
    if(kind==='ftp'){
      // The real record of what FTP has been set to, unsmoothed. It oscillates because most rows
      // are hand-typed - see the tier-3 note - and a smoothed line would be a nicer lie.
      return (st.ftpHistory||[]).filter(function(x){ return x && !x.deleted && +x.ftp>0; })
        .sort(function(a,b){ return _ovwDay_(a.date).localeCompare(_ovwDay_(b.date)); })
        .map(function(x){ return { v:+x.ftp }; });
    }
    var acts=_ovwActs_();
    if(kind==='weekly'){
      var out=[];
      for(var w=11; w>=0; w--){
        out.push({ v:Math.round(_ovwWindow_(acts,(w+1)*7,w*7).reduce(function(s2,a){ return s2+a.dist; },0)*10)/10 });
      }
      return out;
    }
    if(kind==='annual'){
      // Cumulative miles this calendar year, month by month. Ends at the same figure the row shows.
      var yr=_ovwToday_().slice(0,4), by={}, i;
      acts.forEach(function(a){
        if(String(a.date).slice(0,4)!==yr) return;
        var m=String(a.date).slice(5,7); by[m]=(by[m]||0)+a.dist;
      });
      var run=0, res=[], thisM=parseInt(_ovwToday_().slice(5,7),10);
      for(i=1;i<=thisM;i++){
        var k=(i<10?'0':'')+i; run+=(by[k]||0); res.push({ v:Math.round(run) });
      }
      return res;
    }
  }catch(e){}
  return [];
}
// ---- 3. YOUR GOALS ---------------------------------------------------------------------------
// THE REAL GOAL TYPES, which is all of them. Century Ride and Everest Challenge were in the mockup
// and are not goals this app stores - rendering them would have meant inventing two goal types to
// match a picture. Each row shows current against target and the percentage between them; a goal
// with no current reading renders an em-dash rather than 0%.
function _ovwGoalsHTML_(){
  var g=null; try{ g=st.goalTargets||{}; }catch(e){ g={}; }
  var f=null; try{ f=getFitness_(); }catch(e){}
  var rows=[];
  var ytd=null; try{ if(typeof _ytdCycMi_==='function') ytd=_ytdCycMi_(); }catch(e){}
  var wkMi=null;
  try{
    var acts=(typeof _ovwActs_==='function')?_ovwActs_():[];
    wkMi=Math.round(_ovwWindow_(acts,7,0).reduce(function(s,a){ return s+a.dist; },0)*10)/10;
  }catch(e){}
  var wt=null; try{ wt=(typeof stWeightLb_==='function')?stWeightLb_():null; }catch(e){}
  if(g.annualMi>0)  rows.push({ n:'Annual mileage', now:(ytd!=null?Math.round(ytd):null), t:g.annualMi, u:' mi', series:'annual' });
  if(g.weeklyMi>0)  rows.push({ n:'Weekly mileage', now:wkMi, t:g.weeklyMi, u:' mi', series:'weekly' });
  if(g.ctl>0)       rows.push({ n:'Fitness (CTL)', now:(f&&f.loaded)?f.ctl:null, t:g.ctl, u:'', series:'ctl' });
  if(g.ftpW>0)      rows.push({ n:'FTP', now:parseInt((st&&st.ftp)||0,10)||null, t:g.ftpW, u:' W', series:'ftp' });
  // Weight and W/kg are the two where DOWN is progress or the target is a rate, so neither is a
  // simple now/target share. Shown as plain current-vs-target without a bar rather than forced into
  // a percentage that would read backwards.
  if(g.weightLb>0)  rows.push({ n:'Weight', now:wt, t:g.weightLb, u:' lb', noBar:true });
  if(g.wkg>0){
    var wkg=null; try{ if(typeof wkgFromW_==='function' && st.ftp) wkg=wkgFromW_(st.ftp); }catch(e){}
    rows.push({ n:'W/kg at FTP', now:wkg, t:g.wkg, u:'', noBar:true });
  }
  if(!rows.length) return '';
  var H=_ovwLbl_('Your goals', '<span onclick="dsNav(&#39;settings&#39;)" style="font-size:11px;color:var(--d-accent,#fc5200);cursor:pointer">Edit goals</span>');
  rows.forEach(function(r){
    var pct=(r.now!=null && r.t>0)?Math.min(100,Math.round(r.now/r.t*100)):null;
    H+='<div style="margin-bottom:10px">'
      +'<div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px">'
      +'<span style="font-size:12.5px;font-weight:600;color:var(--d-head)">'+r.n+'</span>'
      +'<span style="font-size:11.5px;color:var(--d-t3)">'+((r.now==null)?_ovwDash_():(r.now+r.u))+' / '+r.t+r.u
      +(pct!=null&&!r.noBar?('<b style="color:var(--d-head);margin-left:6px">'+pct+'%</b>'):'')+'</span></div>';
    // A SPARKLINE, NOT A BAR. _gcSpark_ is the shared renderer used everywhere else that shows a
    // trajectory; it returns nothing at all on fewer than two real points, and the row then falls
    // back to the plain number rather than drawing a line through a single reading.
    if(r.series && !r.noBar && typeof _gcSpark_==='function'){
      var sp=_gcSpark_(_ovwGoalSeries_(r.series), '#fc5200', {W:150,H:26});
      if(sp) H+='<div style="margin-top:5px;line-height:0">'+sp+'</div>';
    }
    H+='</div>';
  });
  return _ovwCard_(H);
}

// ---- 4. PERFORMANCE --------------------------------------------------------------------------
// ONE horizontal strip, not the six-card grid. Power figures come from r.powerCurve, the same
// source the DNA power axes read, so the two cannot disagree.
function _ovwPerfHTML_(){
  var live=[]; try{ live=(st.rides||[]).filter(function(r){ return r && !r.deleted; }); }catch(e){}
  var best=function(key){
    var b=null;
    live.forEach(function(r){ var pc=r.powerCurve; if(!pc) return; var v=(pc[key]!=null)?+pc[key]:null;
      if(v>0 && (!b || v>b.w)) b={ w:Math.round(v), date:String(r.date).slice(0,10) }; });
    return b;
  };
  var b5=best('300'), b20=best('1200');
  var longest=null;
  live.forEach(function(r){ var d=parseFloat(r.distance)||0; if(!longest || d>longest.mi) longest={ mi:Math.round(d*10)/10, date:String(r.date).slice(0,10) }; });
  var climb=null;
  try{
    var acts=_ovwActs_();
    var c0=_ovwWindow_(acts,90,0).reduce(function(s,a){return s+a.elev;},0);
    var c1=_ovwWindow_(acts,180,90).reduce(function(s,a){return s+a.elev;},0);
    climb=_ovwPct_(c0,c1);
  }catch(e){}
  // The FIFTH stat the spec asked for and the records-improving COUNT, both missing until now.
  // Distance PRs are the honest source for "improving": dprBoard_ records WHEN each best was set,
  // so a count of markers improved inside 90 days is a date the athlete can check rather than a
  // vibe. It renders an em-dash, not a zero, when the board has not been built.
  var b60=best('3600');
  var improving=null, improvingSub='';
  try{
    if(typeof dprBoard_==='function'){
      var bd=dprBoard_(), cut=_ovwDaysAgo_(90), n=0, total=0;
      (bd.markers||[]).forEach(function(m){
        if(!m.best) return;
        total++;
        var lastStep=(m.progression && m.progression.length)?m.progression[m.progression.length-1]:null;
        if(lastStep && lastStep.date>=cut) n++;
      });
      if(total>0){ improving=n; improvingSub=n+' of '+total+' distance bests, last 90 days'; }
    }
  }catch(e){}
  var cells=[
    { k:'Best 5-min power', v:b5?(b5.w+' W'):null, s:b5?b5.date:'no power curve yet' },
    { k:'Best 20-min power', v:b20?(b20.w+' W'):null, s:b20?b20.date:'no power curve yet' },
    { k:'Best 1-hour power', v:b60?(b60.w+' W'):null, s:b60?b60.date:'no power curve yet' },
    { k:'Longest ride', v:longest?(longest.mi+' mi'):null, s:longest?longest.date:'' },
    { k:'Climbing, 90 days', v:(climb!=null)?((climb>0?'+':'')+climb+'%'):null, s:'vs prior 90 days' },
    { k:'Records improving', v:(improving!=null)?String(improving):null, s:improvingSub||'no distance bests yet' }
  ];
  var H=_ovwLbl_('Performance', '<span onclick="aiSetTab_(&#39;records&#39;)" style="font-size:11px;color:var(--d-accent,#fc5200);cursor:pointer">View records</span>');
  H+='<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 10px">';
  cells.forEach(function(c){
    H+='<div style="min-width:0"><div style="font-size:10.5px;color:var(--d-dim)">'+c.k+'</div>'
      +'<div style="font-size:19px;font-weight:800;color:var(--d-head);margin-top:3px">'+((c.v==null)?_ovwDash_():c.v)+'</div>'
      +'<div style="font-size:9.5px;color:var(--d-dim);margin-top:2px">'+(c.s||'&nbsp;')+'</div></div>';
  });
  return _ovwCard_(H+'</div>');
}

// ============================================================================================
// AI COACH - the generated question.
//
// The first version switched on whichever tier the hierarchy had just fired, which meant the card
// could only ever restate the hero sitting inches away from it. This asks about a CONFLICT instead:
// two facts that are both true and in tension. That is the shape of the brief's own example, and it
// is the only shape that adds something the hero has not already said.
//
// Every candidate carries the EVIDENCE it fired on, and the card prints it. A question the athlete
// cannot trace back to two numbers is just a prompt with a question mark on it.
//
// NOTHING IS INVENTED. Each condition is a comparison between two stored values. When no conflict
// is present the card says so rather than reaching for a generic prompt - the same rule the quiet
// tier follows.
//
// Live conflicts measured while writing this (2026-08-10): volume -40.5% against CTL +3.3%;
// climbing +15.5% against best-20-minute power falling 273 W (2025) to 205 W (2026); a run race in
// 68 days against 13.9 miles run in the last 28; a weight goal 9 lb down alongside a CTL goal 5 up.
var OVW_COACH_COOLDOWN_D=7;     // the same question may not return inside a week

function _ovwBest20ByYear_(){
  var by={};
  try{
    (st.rides||[]).forEach(function(r){
      if(!r || r.deleted || !r.powerCurve || !r.date) return;
      var y=String(r.date).slice(0,4), v=+r.powerCurve['1200']||0;
      if(v>0) by[y]=Math.max(by[y]||0, v);
    });
  }catch(e){}
  return by;
}
function _ovwRunMi_(fromDaysAgo, toDaysAgo){
  var runs=[]; try{ runs=(typeof getRuns==='function')?(getRuns()||[]):[]; }catch(e){}
  var a=_ovwDaysAgo_(fromDaysAgo), b=_ovwDaysAgo_(toDaysAgo);
  return Math.round(runs.filter(function(r){ var d=_ovwDay_(r&&r.date); return d>=a && d<b; })
    .reduce(function(s,r){ return s+(parseFloat(r.distance)||0); },0)*10)/10;
}
function _ovwCand_(id, rank, cat, q, ev){ return { id:id, rank:rank, cat:cat, q:q, ev:ev||[] }; }

// Each generator returns a candidate or null. Ranked: a conflict against a dated COMMITMENT beats a
// conflict between two trends, which beats a conflict between two goals - because the first has a
// deadline attached and the last does not.
function _ovwCoachCandidates_(){
  var out=[], acts=[];
  try{ acts=_ovwActs_(); }catch(e){ acts=[]; }

  // 1. an upcoming race in one sport against the training actually being done for it
  try{
    var races=(typeof upcomingRaces_==='function')?(upcomingRaces_()||[]):[];
    var r0=races.slice().sort(function(a,b){ return String(a.date).localeCompare(String(b.date)); })[0];
    if(r0 && /run/i.test(String(r0.sport||''))){
      var days=Math.round((Date.parse(_ovwDay_(r0.date)+'T00:00:00')-Date.parse(_ovwToday_()+'T00:00:00'))/86400000);
      var mi28=_ovwRunMi_(28,0);
      if(days>0 && days<=120){
        out.push(_ovwCand_('coach:race-vs-run-volume', 1, 'Goal readiness',
          'My next race is a run in '+days+' days and I have run '+mi28+' miles in the last 28. What does the build need to look like?',
          [ (r0.name||'Race')+' on '+_ovwDay_(r0.date)+' - '+days+' days away',
            mi28+' miles run in the last 28 days' ]));
      }
    }
  }catch(e){}

  // 2. training volume down while fitness is not - two measured trends disagreeing
  try{
    var v0=_ovwWindow_(acts,90,0).length, v1=_ovwWindow_(acts,180,90).length;
    var vp=_ovwPct_(v0,v1);
    var ser=(st.fitSeries||[]).slice().sort(function(a,b){ return _ovwDay_(a.date).localeCompare(_ovwDay_(b.date)); });
    if(vp!=null && vp<=-25 && ser.length>=29){
      var cp=_ovwPct_(ser[ser.length-1].ctl, ser[ser.length-29].ctl);
      if(cp!=null && cp>=0){
        out.push(_ovwCand_('coach:volume-vs-fitness', 2, 'Training strategy',
          'I am training '+Math.abs(vp)+'% less than I was, but my fitness has not dropped. Is that real, or is it about to catch up with me?',
          [ v0+' activities in 90 days against '+v1+' in the 90 before',
            'Fitness (CTL) '+(cp>0?'up ':'level, ')+(cp>0?(cp+'% over 28 days'):'over 28 days') ]));
      }
    }
  }catch(e){}

  // 3. climbing rising while sustained power falls - the brief's own example, and real
  try{
    var e0=_ovwWindow_(acts,90,0).reduce(function(s,a){return s+a.elev;},0);
    var e1=_ovwWindow_(acts,180,90).reduce(function(s,a){return s+a.elev;},0);
    var ep=_ovwPct_(e0,e1);
    var by=_ovwBest20ByYear_(), yrs=Object.keys(by).sort();
    if(ep!=null && ep>=15 && yrs.length>=2){
      var thisY=by[yrs[yrs.length-1]], prevY=by[yrs[yrs.length-2]];
      if(thisY>0 && prevY>0 && thisY<prevY){
        out.push(_ovwCand_('coach:climb-vs-power', 2, 'Performance trends',
          'Why has my climbing improved while my sustained power has not?',
          [ 'Climbing up '+ep+'% over 90 days',
            'Best 20-minute power '+prevY+' W in '+yrs[yrs.length-2]+' against '+thisY+' W in '+yrs[yrs.length-1] ]));
      }
    }
  }catch(e){}

  // 4. two goals that pull in opposite directions
  try{
    var g=st.goalTargets||{}, wt=(typeof stWeightLb_==='function')?stWeightLb_():null;
    var f=(typeof getFitness_==='function')?getFitness_():null;
    if(g.weightLb>0 && wt!=null && wt>g.weightLb && g.ctl>0 && f && f.loaded && f.ctl<g.ctl){
      out.push(_ovwCand_('coach:weight-vs-fitness', 3, 'Training strategy',
        'I am trying to lose '+Math.round(wt-g.weightLb)+' lb and add fitness at the same time. Can I do both?',
        [ 'Weight '+wt+' lb against a target of '+g.weightLb,
          'Fitness (CTL) '+f.ctl+' against a target of '+g.ctl ]));
    }
  }catch(e){}

  // 5. the FTP being trained off against the power actually produced this year. Deliberately
  //    conservative: FTP sits near 95% of a 20-minute best by convention, so this only fires when
  //    the gap is well outside that, not merely when the two numbers differ.
  try{
    var by2=_ovwBest20ByYear_(), ys=Object.keys(by2).sort(), cur=ys.length?by2[ys[ys.length-1]]:0;
    var ftp=parseInt((st&&st.ftp)||0,10)||0;
    if(cur>0 && ftp>0 && (cur*0.95) > (ftp*1.10)){
      out.push(_ovwCand_('coach:ftp-vs-power', 2, 'Performance trends',
        'My best 20-minute power this year is '+cur+' W but my FTP is set to '+ftp+'. Which one should I be training off?',
        [ 'Best 20-minute power '+cur+' W in '+ys[ys.length-1], 'FTP setting '+ftp+' W' ]));
    }
  }catch(e){}

  return out;
}

// Pick one. Highest rank wins; ties break on the id so the choice is stable rather than dependent on
// generator order. A question shown inside OVW_COACH_COOLDOWN_D days is skipped, reusing the same
// insight history the hero uses - the keys are namespaced so the two cannot collide.
function ovwCoachQuestion_(){
  var cands=_ovwCoachCandidates_();
  if(!cands.length) return null;
  cands.sort(function(a,b){ return (a.rank-b.rank) || a.id.localeCompare(b.id); });
  var today=_ovwToday_();
  for(var i=0;i<cands.length;i++){
    var c=cands[i], prev=null;
    try{ prev=ovwLastFor_(c.id); }catch(e){}
    if(prev){
      var age=Math.round((Date.parse(today+'T00:00:00')-Date.parse(String(prev.date)+'T00:00:00'))/86400000);
      if(age>=0 && age<OVW_COACH_COOLDOWN_D && String(prev.date)!==today) continue;
    }
    return c;
  }
  return cands[0];      // everything is on cooldown: repeat the best rather than say nothing
}
// The SECOND question, so the card carries real content instead of being padded to match whatever
// tall card it happens to sit beside. Returns nothing when only one conflict exists - a filler
// question chosen by nothing would be exactly the generic prompt this card refuses to show.
function ovwCoachSecond_(primary){
  if(!primary) return null;
  var cands=_ovwCoachCandidates_();
  cands.sort(function(a,b){ return (a.rank-b.rank) || a.id.localeCompare(b.id); });
  for(var i=0;i<cands.length;i++){ if(cands[i].id!==primary.id) return cands[i]; }
  return null;
}

