// Seconds for one activity. movingSecs is authoritative when present; "H:MM:SS" parses via
// parseDurToMin. A BARE number in .duration is raw SECONDS (Strava elapsed leaking through),
// NOT minutes — parseDurToMin reads "4715" as 4715 minutes, i.e. 78 hours. Only 2 activities in
// the library hit that path, but a week total is exactly where one would be visible.
function actSecs_(r){
  if(!r) return 0;
  var ms=parseFloat(r.movingSecs); if(isFinite(ms)&&ms>0) return Math.round(ms);
  if(r.duration==null||r.duration==='') return 0;
  var s=String(r.duration);
  if(s.indexOf(':')>=0) return Math.round(parseDurToMin(s)*60);
  var n=parseFloat(s); return isFinite(n)?Math.round(n):0;
}
// Compact duration for rollup rows: "1h 05m" / "36m".
function fmtHM_(secs){ secs=Math.round(secs||0); var h=Math.floor(secs/3600), m=Math.round((secs%3600)/60); if(m===60){h++;m=0;} return h>0?(h+'h '+(m<10?'0':'')+m+'m'):(m+'m'); }
// The calendar's four activity buckets — the same vocabulary as the calendar type filter
// (calFilter.ride/run/swim/workout), so the breakdown and the filter chips can never disagree.
// A blank sportType/type is a legacy .fit import: all 50 in the library are rides (1,948 mi,
// 50-66 mi outings), which is why the default falls to 'ride'.
function calSportBucket_(r){
  var s=String((typeof rideSport_==='function')?rideSport_(r):'').toLowerCase();
  if(/run|jog|treadmill/.test(s)) return 'run';
  if(/swim/.test(s)) return 'swim';
  if(/weight|strength|lift|workout|hiit|core|gym|mobility|yoga|circuit|conditioning|cardio/.test(s)) return 'workout';
  return 'ride';
}
// Single rollup used by BOTH the Calendar month footer AND each week-row summary
// so they can never diverge. Sums ALL activity types (Miles + TSS include Zwift/
// VirtualRide); rideCount stays type-scoped for the "Rides" label only.
// bySport carries the same figures split into the four buckets above, so the week card can show
// a per-sport breakdown off the same pass that produces the combined total.
// Elevation routes through _actElevGain_, not a bare r.elev: rides store gain in .elev but the
// runs library uses .elevation and some imports carry only the stream, so r.elev alone silently
// reported every run as zero climbing.
// TSS flows through constRideTSS_, the one canonical guard. Summing parseFloat(r.tss) raw made this
// the single loudest wrong number in the app: both calendar renderers and every week card roll up
// through here, so one corrupt import turned January 2026 into "1,593,772 TSS" across 3 activities.
// An unusable value is EXCLUDED and counted in tssUnknown, so a caller can say "n unscored" instead
// of quietly presenting a short total as a complete one.
function calRollup_(list){
  var miles=0, tss=0, rc=0, elev=0, secs=0, tssUnknown=0;
  var by={};
  (list||[]).forEach(function(r){
    var d=parseFloat(r.distance)||0;
    var _t=(typeof constRideTSS_==='function')?constRideTSS_(r):(parseFloat(r.tss)||0);
    var t=(_t==null)?0:_t;
    // A REPAIRED ride still counts as unscored. repairCorruptTss_ zeroes the corrupt value and
    // stamps tssCleared, so without this clause a month of real training whose TSS was unusable
    // would quietly stop saying "n unscored" and start reading as a genuine 0 — reintroducing the
    // exact false-zero F1 removed, just from the other direction.
    if(_t==null && (parseFloat(r.tss)>0 || r.tssCleared)) tssUnknown++;
    var e=(typeof _actElevGain_==='function'?_actElevGain_(r):parseFloat(r.elev))||0;
    var sc=actSecs_(r);
    miles+=d; tss+=t; elev+=e; secs+=sc;
    if(/ride|cycl/i.test(rideSport_(r))) rc++;
    var k=calSportBucket_(r);
    if(!by[k]) by[k]={acts:0,miles:0,tss:0,elev:0,secs:0};
    by[k].acts++; by[k].miles+=d; by[k].tss+=t; by[k].elev+=e; by[k].secs+=sc;
  });
  Object.keys(by).forEach(function(k){
    by[k].miles=Math.round(by[k].miles*10)/10;   // a 3.3 mi run must not round to 3
    by[k].tss=Math.round(by[k].tss); by[k].elev=Math.round(by[k].elev); by[k].secs=Math.round(by[k].secs);
  });
  return {miles:Math.round(miles), tss:Math.round(tss), elev:Math.round(elev), secs:Math.round(secs), acts:(list||[]).length, rideCount:rc, bySport:by, tssUnknown:tssUnknown};
}
// The per-sport week lines, built ONCE and rendered by both the desktop week rail and the mobile
// WK column — only the icon helper and the type sizes differ per surface.
//   Ride: distance / TSS / elevation.  Run: distance / time / elevation.  Swim: distance / time.
// Strength and other non-distance work carries time only, so it is represented rather than
// silently folded into a combined total it still inflates.
// A zero term is DROPPED, never printed: "0 ft" on a week whose runs carry no elevation data is
// the same false claim as an insight calling an unmeasured route flat.
function calSportRows_(roll){
  var order=[['ride','Ride','Ride'],['run','Run','Run'],['swim','Swim','Swim'],['workout','Other','Strength']];
  var by=(roll&&roll.bySport)||{}, out=[];
  order.forEach(function(p){
    var b=by[p[0]]; if(!b||!b.acts) return;
    var main=(p[0]!=='workout'&&b.miles>0)?(b.miles+' mi'):fmtHM_(b.secs), sub=[];
    if(p[0]==='ride'){ if(b.tss) sub.push(b.tss+' TSS'); if(b.elev) sub.push(b.elev+' ft'); }
    else if(p[0]==='run'){ if(b.secs) sub.push(fmtHM_(b.secs)); if(b.elev) sub.push(b.elev+' ft'); }
    else if(p[0]==='swim'){ if(b.secs) sub.push(fmtHM_(b.secs)); }
    else if(b.tss) sub.push(b.tss+' TSS');
    out.push({key:p[0], label:p[1], sport:p[2], main:main, sub:sub.join(' · '), acts:b.acts});
  });
  return out;
}
// Single source of truth for the layout decision: a persisted manual override
// wins, otherwise the width threshold (shared with the head bootstrap via
// AIQ_DESKTOP_MIN). Every layout branch in the app routes through this, and
// the desktop/mobile shell is driven by the html.aiq-desktop / .aiq-mobile
// class that syncLayoutClass_() stamps from it — so detection and layout can
// no longer diverge.
function isDesktop(){
  var o=null; try{ o=localStorage.getItem('aiq_layout'); }catch(e){}
  if(o==='desktop') return true;
  if(o==='mobile') return false;
  return window.innerWidth >= (window.AIQ_DESKTOP_MIN||1024);
}
// Stamp the layout class on <html> from isDesktop(). Cheap; safe to call on
// every resize and immediately at parse time.
function syncLayoutClass_(){
  var d=isDesktop(), r=document.documentElement;
  if(r){ r.classList.toggle('aiq-desktop', d); r.classList.toggle('aiq-mobile', !d); }
  return d;
}
var _layoutApplied=null;
// Sync the class AND (when desktop) populate the desktop shell — but only the
// first time we enter desktop, so resizing within desktop doesn't re-render.
function applyLayout_(){
  var d=syncLayoutClass_();
  // Announced on every layout pass, so it appears on load AND the moment a resize makes the
  // override contradict the window.
  try{ _renderLayoutOverrideBar_(); }catch(e){}
  if(d && _layoutApplied!==true){ try{ dsInitProfile(); dsNav((typeof _dsCurView!=='undefined'&&_dsCurView)||'dashboard'); }catch(e){} }
  _layoutApplied=d;
}
// A STRANDING override announces itself.
//
// aiq_layout is a real feature, but it beats the width check outright and it survives a reload -
// localStorage is not cleared by Ctrl+Shift+R. So a maximised 1600px desktop window renders a
// 480px phone column with no indication of why, and every instinct (hard refresh, reopen the tab)
// fails. Reported as a rendering bug, which is exactly what it looks like from the outside.
//
// The override is kept. What changes is that it stops being SILENT when it contradicts the window.
var _LAYOUT_BANNER_ID='aiq-layout-override-bar';
function _layoutOverrideMismatch_(){
  var o=null; try{ o=localStorage.getItem('aiq_layout'); }catch(e){}
  if(o!=='desktop' && o!=='mobile') return null;
  var auto=window.innerWidth >= (window.AIQ_DESKTOP_MIN||1024);
  if((o==='desktop')===auto) return null;      // the override agrees with the window: nothing to say
  return { forced:o, autoWouldBe:auto?'desktop':'mobile', width:window.innerWidth };
}
function _renderLayoutOverrideBar_(){
  try{
    var old=document.getElementById(_LAYOUT_BANNER_ID); if(old) old.remove();
    var m=_layoutOverrideMismatch_(); if(!m) return;
    var bar=document.createElement('div');
    bar.id=_LAYOUT_BANNER_ID;
    bar.style.cssText='position:fixed;top:0;left:0;right:0;z-index:9000;background:#FC4C02;color:#fff;font-family:inherit;font-size:12.5px;padding:7px 12px;display:flex;align-items:center;gap:10px;justify-content:center';
    var txt=document.createElement('span');
    txt.textContent='Display mode is locked to '+m.forced+'. Your window is '+m.width+'px wide.';
    var go=document.createElement('button');
    go.textContent='Use '+m.autoWouldBe;
    go.style.cssText='font-family:inherit;font-size:12px;font-weight:700;padding:4px 10px;border-radius:9px;border:1px solid rgba(255,255,255,.55);background:rgba(255,255,255,.14);color:#fff;cursor:pointer;flex-shrink:0';
    go.onclick=function(){ try{ setLayoutOverride_('auto'); }catch(e){} };
    var x=document.createElement('button');
    x.textContent='\u00d7';
    x.setAttribute('aria-label','Dismiss');
    x.style.cssText='font-family:inherit;font-size:17px;line-height:1;padding:0 4px;border:none;background:none;color:#fff;cursor:pointer;opacity:.8;flex-shrink:0';
    x.onclick=function(){ bar.remove(); };
    bar.appendChild(txt); bar.appendChild(go); bar.appendChild(x);
    document.body.appendChild(bar);
  }catch(e){ try{ console.error('[layout-bar]', e && e.message); }catch(_e){} }
}
// Manual override: 'auto' clears it, 'desktop'/'mobile' force it. Persisted so
// the choice survives reloads. Applies immediately (no reload needed).
function setLayoutOverride_(mode){
  try{ if(mode==='auto'){ localStorage.removeItem('aiq_layout'); } else { localStorage.setItem('aiq_layout',mode); } }catch(e){}
  _layoutApplied=null;
  applyLayout_();
}
