// -- Delegated "View" link dispatch -----------------------------------------
// Previously-dead link-styled affordances are tagged with data-view (+ optional
// data-arg). One document-level listener routes them to a whitelisted action,
// so the wiring survives re-renders. Group-B links (no target) stay untagged.
var VIEW_ACTIONS = {
  calendar:  function(){ dsNav('calendar'); },
  aicoach:   function(){ dsNav('aicoach'); },
  nutrition: function(){ dsNav('nutrition'); },
  gear:      function(){ dsNav('gear'); },
  progress:  function(){ showNutr(); },
  // parseInt would NaN a handle and editRideData's if(!r) return would swallow it silently.
  // rideRefFromAttr_ decides by shape, so it reads both a legacy position and a handle.
  editRide:  function(a){ if(typeof editRideData==='function') editRideData(rideRefFromAttr_(a)); },
  // Title pencil -> the proven single-field rename path (stamps markRideEdited_(['name']) so the
  // name holds across Strava/Intervals sync). Full multi-field editor lives behind the [...] menu.
  renameRide:function(a){ if(typeof renameRide==='function') renameRide(rideRefFromAttr_(a)); },
  // Ride-detail [...] overflow -> the shared more-menu (Edit ride data / Rename / Delete).
  rideMore:  function(a){ if(typeof openRideDetailMoreMenu==='function') openRideDetailMoreMenu(rideRefFromAttr_(a)); }
};
document.addEventListener('click', function(e){
  var el = (e.target && e.target.closest) ? e.target.closest('[data-view]') : null;
  if(!el) return;
  var fn = VIEW_ACTIONS[el.getAttribute('data-view')];
  if(fn){ e.preventDefault(); fn(el.getAttribute('data-arg')); }
});
var _dsPrevView='dashboard', _dsCurView='dashboard';
function dsNav(section){
  // Track previous desktop view so screens like Gear can offer a Back button.
  if(section!==_dsCurView){ _dsPrevView=_dsCurView; _dsCurView=section; }
  // A record card's return route survives exactly one hop. Navigating anywhere else by hand drops
  // it, or a ride opened later from Activities would offer "Back to Records" and land the user on
  // a tab they never came from.
  if(section!=='ai' && typeof recClearBack_==='function') recClearBack_();
  document.querySelectorAll('.ds-ni').forEach(function(n){n.classList.remove('on');});
  document.querySelectorAll('.ds-ni').forEach(function(n){
    var oc = n.getAttribute('onclick')||'';
    if(oc.indexOf("'"+section+"'") >= 0) n.classList.add('on');
  });
  var mc = document.getElementById('ds-content');
  var rp = document.getElementById('ds-right-panel');
  if(section === 'activities') {
    dsShowRidesList();
  } else if(section === 'home' || section === 'dashboard') {
    dsShowDashboard();
  } else if(section === 'run') {
    dsShowRun();
  } else if(section === 'calendar') {
    dsShowCalendar();
  } else if(section === 'legacy') {
    // Routed through dsNav rather than called straight off the nav item so the sidebar highlight
    // comes from the SAME matcher every other section uses (it looks for the quoted section name
    // inside the item's onclick). A direct showLegacy() call can never match it — which is why
    // Constellation still does not highlight.
    dsShowLegacy();
  } else if(section === 'analytics') {
  } else if(section === 'nutrition') {
    dsShowNutrition();
  } else if(section === 'weather') {
    dsShowWeather();
  } else if(section === 'plan') {
    dsShowBlockPlan();
  } else if(section === 'ai') {
    dsShowAthleteIntel();
  } else if(section === 'gear') {
    dsShowGear();
  } else if(section === 'aicoach') {
    dsShowAICoach();
  } else if(section === 'settings') {
    dsShowSettings();
  } else {
    dsShowRidesList();
  }
}
