    var wl2=a2.filter(function(a){return a.load>0;});
    var pmc2=fitnessSeries_(); if(!pmc2.length) pmc2=null;
    var _fPlan=getFitness_();
    var ctl2=_fPlan.ctl, atl2=_fPlan.atl, tsb2=_fPlan.tsb;
