      if(dt.getDay()===0) continue;                      // Sunday belongs to _RUN_BUILD
      var bp=null; try{ bp=blockPlanFor_(dk); }catch(e){ continue; }
      if(!bp || !bp.sessions) continue;
      var slot=null;
      bp.sessions.forEach(function(s){ if(!slot && s && s.intent==='easyRun') slot=s; });
      if(!slot) continue;
