      +'<span style="color:var(--t4);flex-shrink:0">'
        +(_lc.src==='picked'?'chosen':_lc.src==='device'?'this device':'default')+' &middot; change</span>';
    locRow.onclick=function(){ if(typeof wxLocOpen_==='function') wxLocOpen_(); };
