// ── CALENDAR INTERACTIVITY: completion, day editor, month view ──────────────
// Parse a 'Y-M-D' key (padded OR unpadded, e.g. 2026-7-8) into a local Date.
// new Date('2026-7-8T00:00:00') is INVALID (ISO needs zero-padding), which was
// producing "undefined, undefined NaN" in the editor title — parse manually.
function parseDayKey(dateKey){
  var p=String(dateKey||'').split('-');
  if(p.length!==3) return new Date(NaN);
  return new Date(parseInt(p[0],10), parseInt(p[1],10)-1, parseInt(p[2],10));
}
// Completion is stored locally (like the avatar) so it never bloats sync.
function getCompletions(){
  try{ return JSON.parse(localStorage.getItem('aiq_completions')||'{}'); }catch(e){ return {}; }
}
function isDayComplete(dateKey){
  var c=getCompletions(); return !!c[dateKey];
}
function toggleDayComplete(dateKey){
  var c=getCompletions();
  var marking=!c[dateKey];
  if(c[dateKey]) delete c[dateKey]; else c[dateKey]=Date.now();
  try{ localStorage.setItem('aiq_completions', JSON.stringify(c)); }catch(e){}
  // Route through the SAME completion path as the editor: marking a day complete should
  // finish + score its logged sessions, not just flip a local display flag. Un-marking
  // leaves session state alone (a completed session with a real log stays completed).
  if(marking){ try{ _scoreDaySessions_(dateKey); }catch(e){} }
  try{ if(typeof toast==='function') toast(marking?'Marked complete':'Marked incomplete'); }catch(e){}
  // Re-render whichever calendar view is active.
  try{ if(typeof showCalendarTab==='function') showCalendarTab(); }catch(e){}
}
// Complete + score the day's sessions that carry real evidence of work (a strength log on the
// session, or a mobility actual duration). No evidence -> left untouched: marking a day complete
// never fabricates a completed status on an un-logged session. Score is computed AFTER status is
// set, since computeExecutionScore_ returns null unless status==='completed'.
function _scoreDaySessions_(dateKey){
  if(typeof st==='undefined' || !st.plan) return;
  var nk=(typeof normDate==='function')?normDate(dateKey):dateKey;
  var day=st.plan[nk]; if(!day||!Array.isArray(day.sessions)) return;
  var changed=false;
  day.sessions.forEach(function(s){
    if(!s || s.deleted || s.type==='rest') return;
    var hasLog=(s.type==='strength' && Array.isArray(s.strengthLog) && s.strengthLog.length);
    var hasActual=(s.type==='mobility' && s.actualDurationMin!=null);
    if(!hasLog && !hasActual) return;
    s.status='completed';
    if(typeof computeExecutionScore_==='function') s.executionScore=computeExecutionScore_(s);
    if(typeof markPlanEdited_==='function') markPlanEdited_(s, s.executionScore!=null?['status','executionScore']:['status']);
    changed=true;
  });
  if(changed){ try{ if(typeof sv==='function') sv(); }catch(e){} }
}

// Day match for an activity date. Extracted so findActivityForDate and activitiesForDate_ share ONE
// rule — a second copy of this comparison is exactly how the timezone bug below would come back.
// A date-only (or leading-date) string like '2026-07-25' must be compared AS WRITTEN. new Date()
// treats it as UTC midnight, which rolls back a calendar day in a behind-UTC timezone (Michigan) —
// so today's ride read as yesterday and Dr. Smurkel never flipped to its post-ride state. Compare the
// normalized YYYY-MM-DD directly; only fall back to Date parsing for a genuine timestamp value.
function _actSameDay_(ds, keyNorm, target){
  if(!ds) return false;
  var s=String(ds);
  var m=s.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})/);
  if(m){ return ((typeof normDate==='function')?normDate(s.slice(0,10)):s.slice(0,10))===keyNorm; }
  var d=new Date(s);
  return d.getFullYear()===target.getFullYear() && d.getMonth()===target.getMonth() && d.getDate()===target.getDate();
}
// The SPORT of an activity, which is NOT the array it was found in. st.rides holds every sport —
// a Strava-imported run lives there too — so 'kind' only ever meant "which list", and reading it as
// "is a bike ride" let a run satisfy a ride day. Classify off the sport field, same vocabulary the
// You-vs-You page uses.
function _actSport_(obj, fallback){
  var s=(typeof rideSport_==='function')?rideSport_(obj):String((obj&&(obj.sportType||obj.type))||'');
  s=String(s).replace(/[ _-]/g,'');
  if(/^(run|trailrun|virtualrun|treadmill)$/i.test(s)) return 'run';
  if(/^(swim|openwaterswim|opanwaterswim|walk|hike|weighttraining|workout|strength|crossfit|yoga|elliptical|rowing)$/i.test(s)) return 'other';
  if(!s) return fallback||'ride';
  return 'ride';
}
// EVERY completed activity for a date key (Y-M-D), each tagged with its real sport. Callers that
// need a specific modality filter on .sport; callers that just want "something happened" take [0].
function activitiesForDate_(dateKey){
  var target=parseDayKey(dateKey);
  var keyNorm=(typeof normDate==='function')?normDate(dateKey):String(dateKey||'');
  var out=[];
  var rides=(st.rides||[]);
  for(var i=0;i<rides.length;i++){ var r=rides[i];
    if(r && !r.deleted && _actSameDay_(r.date, keyNorm, target)) out.push({kind:'ride', obj:r, idx:i, sport:_actSport_(r,'ride')}); }
  var runs=(st.runs||[]);
  for(var j=0;j<runs.length;j++){ var u=runs[j];
    if(u && !u.deleted && _actSameDay_(u.date, keyNorm, target)) out.push({kind:'run', obj:u, idx:j, sport:'run'}); }
  return out;
}
// Find a completed activity (ride or run) for a given date key (Y-M-D). Unchanged semantics: the
// first st.rides match, else the first st.runs match.
function findActivityForDate(dateKey){
  var all=activitiesForDate_(dateKey);
  return all.length?all[0]:null;
}

// Tap a day -> open the day-detail editor. Dual-mode:
//  - if a completed activity exists for that date, edit that activity
//  - otherwise edit the planned workout name for that date
// Session presets — picking one sets type + intent + name TOGETHER so they can
// never disagree (free-text naming is what fragmented "Streach" and would corrupt
// the 1RM/progression history). Pulled forward from Phase 1 per the strength spec.
// DERIVED from SESSION_DEFS (the one source) so the dropdown can never drift from the generator.
// Same order, plus the free-text "Other…" escape hatch.
var SESSION_PRESETS=(function(){
  var out=SESSION_DEF_ORDER.map(function(k){ var d=SESSION_DEFS[k]; return {v:k, label:d.name, type:d.type, intent:(d.type==='rest'?'':k), name:d.name}; });
  out.push({v:'other', label:'Other…', type:'', intent:'', name:''});
  return out;
})();
// Exercise library (spec 3.2-3.4) with default sets/reps/%1RM. The per-row exercise
// dropdown prefills from here (reps: carries=meters, mobility=reps or seconds).
// Exercise library. The four strength groups rotate A -> B -> C -> D across the two weekly slots;
// see STRENGTH_POOL_ and strengthForSlot_. Every group carries calf/shin work (calf raise, toe
// raises, banded dorsiflexion, heel drops) and a hip-flexor or quad opener, because those are the
// areas cycling never loads and the rotation must not let a fortnight pass without them.
//
// reps doubles as SECONDS for a hold and METRES for a carry - the convention this library already
// used for loaded carries. pct1RM is blank on anything not barbell/dumbbell loaded: strengthRx_
// prices a working weight off a stored 1RM, and a movement with no 1RM on file must render blank
// rather than invent a number.
//
// Toe yoga and towel scrunches are deliberately ABSENT. They are a daily one-to-two-minute
// practice, not gym line items, and listing them here would put them in a scored session.
// New name -> the key a stored 1RM may still sit under. Read-time only.
